INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-5-02', 'awl-5', 'Học thuật Sublist 5 · Bộ 2', 'Academic Word List, sublist 5', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 1, 'licence', 'giấy phép; bằng lái', 'noun', '[{"en":"Foreign banks must obtain a licence before operating in the country.","vi":"Ngân hàng nước ngoài phải có giấy phép trước khi hoạt động tại quốc gia này."},{"en":"The company lost its licence after failing a safety inspection.","vi":"Công ty bị tước giấy phép sau khi không đạt đợt kiểm tra an toàn."},{"en":"She passed her test and got her driving licence last month.","vi":"Cô ấy đã thi đỗ và nhận bằng lái xe vào tháng trước."}]', '[{"phrase":"obtain a licence"},{"phrase":"apply for a licence"},{"phrase":"driving licence"}]', 'Anh: licence (n) · Mỹ: license', '/ˈlaɪsns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lic/licen/licence__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 2, 'logic', 'logic; lập luận; lý lẽ', 'noun', '[{"en":"I don''t understand the logic behind the new policy.","vi":"Tôi không hiểu lập luận đằng sau chính sách mới."},{"en":"Her argument was based on simple logic and clear evidence.","vi":"Lý lẽ của cô ấy dựa trên logic đơn giản và bằng chứng rõ ràng."},{"en":"Students study formal logic in their first year of philosophy.","vi":"Sinh viên học logic hình thức trong năm đầu ngành triết học."}]', '[{"phrase":"logic behind"},{"phrase":"formal logic"},{"phrase":"simple logic"}]', 'không đếm được', '/ˈlɑːdʒɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/log/logic/logic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 3, 'margin', 'lề; cách biệt; biên lợi nhuận', 'noun', '[{"en":"Please leave a wide margin on the left side of the page.","vi":"Vui lòng chừa lề rộng ở bên trái trang giấy."},{"en":"The proposal was approved by a narrow margin of three votes.","vi":"Đề xuất được thông qua với cách biệt sít sao là ba phiếu."},{"en":"Rising costs have reduced profit margins across the industry.","vi":"Chi phí tăng đã làm giảm biên lợi nhuận trên toàn ngành."}]', '[{"phrase":"profit margin"},{"phrase":"narrow margin"},{"phrase":"margin of error"}]', NULL, '/ˈmɑːrdʒɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/margi/margin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 4, 'medical', '(thuộc) y tế; y khoa', 'adjective', '[{"en":"The clinic provides free medical care to local families.","vi":"Phòng khám cung cấp dịch vụ chăm sóc y tế miễn phí cho các gia đình địa phương."},{"en":"She is in her third year at medical school.","vi":"Cô ấy đang học năm thứ ba trường y."},{"en":"New medical research suggests that regular exercise improves memory.","vi":"Nghiên cứu y khoa mới cho thấy tập thể dục thường xuyên giúp cải thiện trí nhớ."}]', '[{"phrase":"medical care"},{"phrase":"medical research"},{"phrase":"medical school"},{"phrase":"medical treatment"}]', NULL, '/ˈmedɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/medic/medical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 5, 'mental', '(thuộc) tinh thần; trí tuệ; trí óc', 'adjective', '[{"en":"Regular exercise is good for both physical and mental health.","vi":"Tập thể dục thường xuyên tốt cho cả sức khỏe thể chất lẫn tinh thần."},{"en":"The study measured how stress affects children''s mental development.","vi":"Nghiên cứu đã đo lường mức độ ảnh hưởng của căng thẳng đến sự phát triển trí tuệ của trẻ em."},{"en":"Solving puzzles is a good mental exercise for older adults.","vi":"Giải câu đố là một cách rèn luyện trí óc tốt cho người cao tuổi."}]', '[{"phrase":"mental health"},{"phrase":"mental development"},{"phrase":"physical and mental"}]', NULL, '/ˈmentl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menta/mental__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 6, 'modify', 'sửa đổi; điều chỉnh; biến đổi', 'verb', '[{"en":"The engineers modified the design to reduce the car''s weight.","vi":"Các kỹ sư đã điều chỉnh thiết kế để giảm trọng lượng của chiếc xe."},{"en":"We may need to modify our plans if the budget is cut.","vi":"Chúng ta có thể cần sửa đổi kế hoạch nếu ngân sách bị cắt giảm."},{"en":"Scientists have genetically modified the plant to resist disease.","vi":"Các nhà khoa học đã biến đổi gen của loại cây này để nó kháng bệnh."}]', '[{"phrase":"modify the design"},{"phrase":"slightly modify"},{"phrase":"genetically modified"}]', NULL, '/ˈmɑːdɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/modif/modify__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 7, 'monitor', 'theo dõi; giám sát', 'verb', '[{"en":"Nurses monitor patients closely during the first night after surgery.","vi":"Y tá theo dõi sát bệnh nhân trong đêm đầu tiên sau phẫu thuật."},{"en":"The government is monitoring air quality in major cities.","vi":"Chính phủ đang giám sát chất lượng không khí ở các thành phố lớn."},{"en":"Managers should monitor progress regularly to keep the project on schedule.","vi":"Các nhà quản lý nên thường xuyên theo dõi tiến độ để dự án đúng kế hoạch."}]', '[{"phrase":"monitor progress"},{"phrase":"closely monitor"},{"phrase":"monitor the situation"}]', 'cũng là danh từ: màn hình', '/ˈmɑːnɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/monit/monitor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 8, 'network', 'mạng lưới; mạng (máy tính)', 'noun', '[{"en":"The city is building a new network of bike lanes.","vi":"Thành phố đang xây dựng một mạng lưới làn đường xe đạp mới."},{"en":"All the office computers are connected to the same network.","vi":"Tất cả máy tính trong văn phòng đều được kết nối vào cùng một mạng."},{"en":"Attending conferences helps young researchers build a professional network.","vi":"Tham dự hội thảo giúp các nhà nghiên cứu trẻ xây dựng mạng lưới quan hệ nghề nghiệp."}]', '[{"phrase":"network of"},{"phrase":"computer network"},{"phrase":"professional network"},{"phrase":"transport network"}]', NULL, '/ˈnetwɜːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/net/netwo/network__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 9, 'notion', 'khái niệm; quan niệm', 'noun', '[{"en":"The study challenges the notion that older workers are less productive.","vi":"Nghiên cứu này thách thức quan niệm rằng người lao động lớn tuổi làm việc kém năng suất hơn."},{"en":"Many students have only a vague notion of how interest rates work.","vi":"Nhiều sinh viên chỉ có khái niệm mơ hồ về cách lãi suất vận hành."},{"en":"The notion of fairness varies from one culture to another.","vi":"Khái niệm công bằng khác nhau giữa các nền văn hóa."}]', '[{"phrase":"the notion that"},{"phrase":"notion of"},{"phrase":"challenge the notion"},{"phrase":"vague notion"}]', NULL, '/ˈnəʊʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notio/notion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 10, 'objective', 'mục tiêu; mục đích', 'noun', '[{"en":"The main objective of the project is to reduce energy costs.","vi":"Mục tiêu chính của dự án là giảm chi phí năng lượng."},{"en":"Each lesson begins with a clear list of learning objectives.","vi":"Mỗi bài học bắt đầu bằng một danh sách rõ ràng các mục tiêu học tập."},{"en":"The company achieved all of its objectives for the year.","vi":"Công ty đã đạt được tất cả các mục tiêu đề ra cho năm nay."}]', '[{"phrase":"main objective"},{"phrase":"achieve an objective"},{"phrase":"learning objectives"}]', 'cũng là tính từ: khách quan', '/əbˈdʒektɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obj/objec/objective__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 11, 'orient', 'định hướng; hướng (vào)', 'verb', '[{"en":"The new course is oriented toward students who plan to work abroad.","vi":"Khóa học mới hướng tới những sinh viên dự định làm việc ở nước ngoài."},{"en":"Most of the firm''s products are oriented to the export market.","vi":"Phần lớn sản phẩm của công ty hướng tới thị trường xuất khẩu."},{"en":"The government wants to orient the economy toward services and technology.","vi":"Chính phủ muốn định hướng nền kinh tế sang dịch vụ và công nghệ."}]', '[{"phrase":"oriented toward"},{"phrase":"orient yourself"},{"phrase":"market-oriented"}]', 'thường dùng bị động: be oriented to/toward · Anh còn dùng: orientate', '/ˈɔːrient/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/orien/orient__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 12, 'perspective', 'góc nhìn; quan điểm', 'noun', '[{"en":"The book tells the story of migration from a child''s perspective.","vi":"Cuốn sách kể câu chuyện di cư từ góc nhìn của một đứa trẻ."},{"en":"Living abroad gave me a completely different perspective on my own culture.","vi":"Sống ở nước ngoài cho tôi một góc nhìn hoàn toàn khác về văn hóa của chính mình."},{"en":"From an economic perspective, the plan makes a lot of sense.","vi":"Xét từ quan điểm kinh tế, kế hoạch này rất hợp lý."}]', '[{"phrase":"different perspective"},{"phrase":"perspective on"},{"phrase":"from an economic perspective"}]', 'perspective on + danh từ', '/pərˈspektɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persp/perspective__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 13, 'precise', 'chính xác; cụ thể', 'adjective', '[{"en":"Scientific instruments must give precise measurements under all conditions.","vi":"Các thiết bị khoa học phải cho kết quả đo chính xác trong mọi điều kiện."},{"en":"The precise cause of the delay is still unclear.","vi":"Nguyên nhân chính xác của sự chậm trễ vẫn chưa rõ."},{"en":"Could you be more precise about what the client wants?","vi":"Bạn có thể nói cụ thể hơn về việc khách hàng muốn gì không?"}]', '[{"phrase":"precise measurement"},{"phrase":"precise details"},{"phrase":"to be precise"}]', NULL, '/prɪˈsaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preci/precise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 14, 'prime', 'chính; hàng đầu; đắc địa', 'adjective', '[{"en":"Cost is the prime concern for most small businesses.","vi":"Chi phí là mối quan tâm hàng đầu của hầu hết các doanh nghiệp nhỏ."},{"en":"The hotel is in a prime location near the city center.","vi":"Khách sạn nằm ở vị trí đắc địa gần trung tâm thành phố."},{"en":"Poor diet is a prime example of a health risk people can control.","vi":"Chế độ ăn uống kém là ví dụ điển hình về một rủi ro sức khỏe mà con người có thể kiểm soát."}]', '[{"phrase":"prime example"},{"phrase":"prime location"},{"phrase":"prime concern"}]', NULL, '/praɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prime/prime__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 15, 'psychology', 'tâm lý học; tâm lý', 'noun', '[{"en":"She has a degree in psychology and works in a hospital.","vi":"Cô ấy có bằng tâm lý học và làm việc tại một bệnh viện."},{"en":"Understanding customer psychology is essential for successful marketing.","vi":"Hiểu tâm lý khách hàng là điều thiết yếu để tiếp thị thành công."},{"en":"Child psychology studies how children think, feel and learn.","vi":"Tâm lý học trẻ em nghiên cứu cách trẻ suy nghĩ, cảm nhận và học hỏi."}]', '[{"phrase":"child psychology"},{"phrase":"degree in psychology"},{"phrase":"social psychology"}]', NULL, '/saɪˈkɑːlədʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/psy/psych/psychology__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 16, 'pursue', 'theo đuổi; tiếp tục (thực hiện)', 'verb', '[{"en":"After graduating, he decided to pursue a career in law.","vi":"Sau khi tốt nghiệp, anh ấy quyết định theo đuổi sự nghiệp trong ngành luật."},{"en":"Many students go abroad to pursue further studies.","vi":"Nhiều sinh viên ra nước ngoài để tiếp tục học lên cao."},{"en":"The committee agreed not to pursue the matter any further.","vi":"Ủy ban nhất trí không tiếp tục theo đuổi vấn đề này nữa."}]', '[{"phrase":"pursue a career"},{"phrase":"pursue a goal"},{"phrase":"pursue the matter"}]', NULL, '/pərˈsuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/pursu/pursue__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 17, 'ratio', 'tỷ lệ; tỷ số', 'noun', '[{"en":"The ratio of students to teachers in the school is twenty to one.","vi":"Tỷ lệ học sinh trên giáo viên ở trường này là hai mươi trên một."},{"en":"The gender ratio in engineering courses is slowly becoming more balanced.","vi":"Tỷ lệ giới tính trong các khóa học kỹ thuật đang dần cân bằng hơn."},{"en":"Mix the flour and water in a ratio of two to one.","vi":"Trộn bột và nước theo tỷ lệ hai phần bột, một phần nước."}]', '[{"phrase":"the ratio of"},{"phrase":"in a ratio of"},{"phrase":"gender ratio"}]', 'ratio of A to B = tỷ lệ A trên B', '/ˈreɪʃiəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/ratio/ratio__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 18, 'reject', 'từ chối; bác bỏ', 'verb', '[{"en":"The board rejected the proposal because it was too expensive.","vi":"Hội đồng quản trị đã bác bỏ đề xuất vì nó quá tốn kém."},{"en":"Her first article was rejected by three journals.","vi":"Bài báo đầu tiên của cô ấy đã bị ba tạp chí từ chối."},{"en":"Scientists rejected the theory after new evidence was found.","vi":"Các nhà khoa học đã bác bỏ lý thuyết đó sau khi tìm ra bằng chứng mới."}]', '[{"phrase":"reject a proposal"},{"phrase":"reject an application"},{"phrase":"flatly reject"}]', NULL, '/rɪˈdʒekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rej/rejec/reject__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 19, 'revenue', 'doanh thu; nguồn thu', 'noun', '[{"en":"The company''s revenue rose by twelve percent last year.","vi":"Doanh thu của công ty đã tăng mười hai phần trăm vào năm ngoái."},{"en":"Tourism is the country''s main source of revenue.","vi":"Du lịch là nguồn thu chính của đất nước."},{"en":"The government expects tax revenues to increase next year.","vi":"Chính phủ dự kiến nguồn thu thuế sẽ tăng vào năm tới."}]', '[{"phrase":"tax revenue"},{"phrase":"source of revenue"},{"phrase":"generate revenue"}]', NULL, '/ˈrevənuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/reven/revenue__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 20, 'stable', 'ổn định; vững chắc', 'adjective', '[{"en":"Prices have remained stable for the past six months.","vi":"Giá cả vẫn ổn định trong sáu tháng qua."},{"en":"Investors prefer countries with a stable economy.","vi":"Các nhà đầu tư ưa chuộng những quốc gia có nền kinh tế ổn định."},{"en":"Make sure the ladder is stable before you climb it.","vi":"Hãy chắc chắn rằng cái thang đã đứng vững trước khi bạn trèo lên."}]', '[{"phrase":"remain stable"},{"phrase":"stable economy"},{"phrase":"stable job"}]', NULL, '/ˈsteɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stabl/stable__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 21, 'style', 'phong cách; kiểu; lối (viết)', 'noun', '[{"en":"Every manager has a different leadership style.","vi":"Mỗi nhà quản lý có một phong cách lãnh đạo khác nhau."},{"en":"The building was designed in a traditional Japanese style.","vi":"Tòa nhà được thiết kế theo kiểu truyền thống Nhật Bản."},{"en":"His writing style is clear, simple and easy to follow.","vi":"Lối viết của anh ấy rõ ràng, đơn giản và dễ hiểu."}]', '[{"phrase":"leadership style"},{"phrase":"writing style"},{"phrase":"learning style"}]', NULL, '/staɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sty/style/style__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 22, 'substitute', 'thay thế', 'verb', '[{"en":"You can substitute olive oil for butter in this recipe.","vi":"Bạn có thể dùng dầu ô liu thay cho bơ trong công thức này."},{"en":"Many factories have substituted machines for human workers.","vi":"Nhiều nhà máy đã thay thế công nhân bằng máy móc."},{"en":"Online classes cannot fully substitute for face-to-face teaching.","vi":"Các lớp học trực tuyến không thể thay thế hoàn toàn việc giảng dạy trực tiếp."}]', '[{"phrase":"substitute for"},{"phrase":"substitute one thing for another"}]', 'substitute A for B = dùng A thay cho B · cũng là danh từ: vật/người thay thế', '/ˈsʌbstɪtuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substitute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 23, 'sustain', 'duy trì; chịu (thiệt hại)', 'verb', '[{"en":"The company cannot sustain such rapid growth for long.","vi":"Công ty không thể duy trì tốc độ tăng trưởng nhanh như vậy lâu dài."},{"en":"The region''s economy is sustained mainly by fishing and tourism.","vi":"Nền kinh tế của khu vực được duy trì chủ yếu nhờ đánh bắt cá và du lịch."},{"en":"Several buildings sustained serious damage during the storm.","vi":"Nhiều tòa nhà bị thiệt hại nghiêm trọng trong cơn bão."}]', '[{"phrase":"sustain growth"},{"phrase":"sustain damage"},{"phrase":"sustain interest"}]', NULL, '/səˈsteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/susta/sustain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 24, 'symbol', 'biểu tượng; ký hiệu', 'noun', '[{"en":"The old bridge has become a symbol of the city.","vi":"Cây cầu cũ đã trở thành biểu tượng của thành phố."},{"en":"In chemistry, the symbol for gold is Au.","vi":"Trong hóa học, ký hiệu của vàng là Au."},{"en":"For many families, owning a car is a symbol of success.","vi":"Với nhiều gia đình, sở hữu ô tô là biểu tượng của sự thành công."}]', '[{"phrase":"symbol of"},{"phrase":"status symbol"},{"phrase":"chemical symbol"}]', NULL, '/ˈsɪmbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sym/symbo/symbol__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 25, 'target', 'mục tiêu; chỉ tiêu; đối tượng', 'noun', '[{"en":"The factory failed to meet its production target this year.","vi":"Nhà máy đã không đạt chỉ tiêu sản xuất trong năm nay."},{"en":"Young adults are the main target of the advertising campaign.","vi":"Người trẻ tuổi là đối tượng chính của chiến dịch quảng cáo."},{"en":"The government has set a target of cutting emissions by half.","vi":"Chính phủ đã đặt mục tiêu cắt giảm một nửa lượng khí thải."}]', '[{"phrase":"meet a target"},{"phrase":"set a target"},{"phrase":"sales target"},{"phrase":"target audience"}]', NULL, '/ˈtɑːrɡɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tar/targe/target__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 26, 'transit', 'sự vận chuyển; quá cảnh; giao thông công cộng', 'noun', '[{"en":"Some of the goods were damaged in transit.","vi":"Một số hàng hóa đã bị hư hỏng trong quá trình vận chuyển."},{"en":"Passengers in transit do not need a visa at this airport.","vi":"Hành khách quá cảnh không cần thị thực tại sân bay này."},{"en":"The city plans to invest heavily in public transit.","vi":"Thành phố dự định đầu tư mạnh vào giao thông công cộng."}]', '[{"phrase":"in transit"},{"phrase":"public transit"},{"phrase":"transit visa"}]', 'public transit (Mỹ) = public transport (Anh)', '/ˈtrænzɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transit__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 27, 'trend', 'xu hướng; khuynh hướng', 'noun', '[{"en":"There is a growing trend toward working from home.","vi":"Xu hướng làm việc tại nhà đang ngày càng gia tăng."},{"en":"Economists study long-term trends in employment and wages.","vi":"Các nhà kinh tế học nghiên cứu xu hướng dài hạn về việc làm và tiền lương."},{"en":"If this trend continues, prices will double within ten years.","vi":"Nếu xu hướng này tiếp diễn, giá cả sẽ tăng gấp đôi trong vòng mười năm."}]', '[{"phrase":"growing trend"},{"phrase":"long-term trend"},{"phrase":"trend toward"},{"phrase":"current trend"}]', NULL, '/trend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/trend/trend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 28, 'version', 'phiên bản; bản', 'noun', '[{"en":"Please download the latest version of the software.","vi":"Vui lòng tải phiên bản mới nhất của phần mềm."},{"en":"The final version of the report is due on Friday.","vi":"Bản cuối cùng của báo cáo phải nộp vào thứ Sáu."},{"en":"The English version of the book will be published next year.","vi":"Bản tiếng Anh của cuốn sách sẽ được xuất bản vào năm sau."}]', '[{"phrase":"latest version"},{"phrase":"final version"},{"phrase":"updated version"},{"phrase":"English version"}]', NULL, '/ˈvɜːrʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/versi/version__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 29, 'welfare', 'phúc lợi; an sinh', 'noun', '[{"en":"The new law aims to improve the welfare of factory workers.","vi":"Luật mới nhằm cải thiện phúc lợi cho công nhân nhà máy."},{"en":"Spending on social welfare has increased sharply this decade.","vi":"Chi tiêu cho phúc lợi xã hội đã tăng mạnh trong thập kỷ này."},{"en":"Animal welfare groups are calling for better conditions on farms.","vi":"Các tổ chức bảo vệ phúc lợi động vật đang kêu gọi cải thiện điều kiện ở các trang trại."}]', '[{"phrase":"social welfare"},{"phrase":"animal welfare"},{"phrase":"welfare of"},{"phrase":"welfare system"}]', 'không đếm được', '/ˈwelfer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/welfa/welfare__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-5-02', 30, 'whereas', 'trong khi; còn', 'conjunction', '[{"en":"Some students prefer group work, whereas others learn better alone.","vi":"Một số sinh viên thích làm việc nhóm, trong khi những người khác học tốt hơn khi học một mình."},{"en":"Rents have risen sharply, whereas wages have barely changed.","vi":"Tiền thuê nhà tăng mạnh, trong khi tiền lương hầu như không thay đổi."},{"en":"Whereas the old system was slow, the new one processes orders instantly.","vi":"Hệ thống cũ chạy chậm, còn hệ thống mới xử lý đơn hàng ngay lập tức."}]', '[{"phrase":"whereas others"},{"phrase":"whereas in the past"}]', 'dùng để đối chiếu hai mệnh đề trái ngược', '/ˌwerˈæz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/whereas__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-6-01', 'awl-6', 'Học thuật Sublist 6 · Bộ 1', 'Academic Word List, sublist 6', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 1, 'abstract', 'trừu tượng', 'adjective', '[{"en":"Young children often find abstract concepts like time hard to understand.","vi":"Trẻ nhỏ thường thấy khó hiểu những khái niệm trừu tượng như thời gian."},{"en":"The lecture was too abstract for most first-year students.","vi":"Bài giảng quá trừu tượng đối với hầu hết sinh viên năm nhất."},{"en":"Try to give concrete examples instead of abstract explanations.","vi":"Hãy cố gắng đưa ra ví dụ cụ thể thay vì những lời giải thích trừu tượng."}]', '[{"phrase":"abstract concept"},{"phrase":"abstract idea"},{"phrase":"abstract art"}]', 'abstract ≠ concrete (cụ thể); danh từ abstract = bản tóm tắt (bài báo khoa học)', '/ˈæbstrækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/abstr/abstract__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 2, 'accurate', 'chính xác', 'adjective', '[{"en":"Accurate data is essential for making good policy decisions.","vi":"Dữ liệu chính xác là yếu tố thiết yếu để đưa ra các quyết định chính sách đúng đắn."},{"en":"The weather forecast was not very accurate this week.","vi":"Dự báo thời tiết tuần này không chính xác lắm."},{"en":"Is this a fairly accurate description of what happened at the meeting?","vi":"Đây có phải là mô tả khá chính xác về những gì đã diễn ra trong cuộc họp không?"}]', '[{"phrase":"accurate information"},{"phrase":"accurate data"},{"phrase":"accurate description"},{"phrase":"highly accurate"}]', NULL, '/ˈækjərət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accur/accurate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 3, 'acknowledge', 'thừa nhận; ghi nhận; xác nhận (đã nhận)', 'verb', '[{"en":"The company finally acknowledged that the product had a serious fault.","vi":"Công ty cuối cùng đã thừa nhận rằng sản phẩm có lỗi nghiêm trọng."},{"en":"The report acknowledges the contribution of local volunteers.","vi":"Báo cáo ghi nhận sự đóng góp của các tình nguyện viên địa phương."},{"en":"Please acknowledge receipt of this email by Friday.","vi":"Vui lòng xác nhận đã nhận được email này trước thứ Sáu."}]', '[{"phrase":"acknowledge receipt"},{"phrase":"widely acknowledged"},{"phrase":"acknowledge the need"},{"phrase":"acknowledge the contribution"}]', 'acknowledge + that / V-ing', '/əkˈnɑːlɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ack/ackno/acknowledge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 4, 'aggregate', 'tổng; tổng hợp', 'adjective', '[{"en":"Aggregate demand fell sharply during the economic crisis.","vi":"Tổng cầu giảm mạnh trong cuộc khủng hoảng kinh tế."},{"en":"The study only reports aggregate data, not individual results.","vi":"Nghiên cứu chỉ báo cáo dữ liệu tổng hợp, không báo cáo kết quả của từng cá nhân."},{"en":"Our team finished first with an aggregate score of 245 points.","vi":"Đội chúng tôi về nhất với tổng điểm là 245."}]', '[{"phrase":"aggregate demand"},{"phrase":"aggregate data"},{"phrase":"aggregate score"}]', NULL, '/ˈæɡrɪɡət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agg/aggre/aggregate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 5, 'allocate', 'phân bổ; cấp; dành (cho)', 'verb', '[{"en":"The government allocated extra funds to rural hospitals this year.","vi":"Năm nay chính phủ đã phân bổ thêm kinh phí cho các bệnh viện ở nông thôn."},{"en":"Each student will be allocated a room in student housing.","vi":"Mỗi sinh viên sẽ được cấp một phòng trong khu nhà ở sinh viên."},{"en":"We need to allocate more time to testing before the launch.","vi":"Chúng ta cần dành thêm thời gian cho việc kiểm thử trước khi ra mắt."}]', '[{"phrase":"allocate resources"},{"phrase":"allocate funds"},{"phrase":"allocate time"}]', 'allocate sth to sb/sth', '/ˈæləkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/alloc/allocate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 6, 'assign', 'giao (việc); phân công; chỉ định', 'verb', '[{"en":"The manager assigned the new project to two experienced engineers.","vi":"Người quản lý đã giao dự án mới cho hai kỹ sư giàu kinh nghiệm."},{"en":"Patients were randomly assigned to one of three groups.","vi":"Các bệnh nhân được phân ngẫu nhiên vào một trong ba nhóm."},{"en":"Each student is assigned a tutor in their first week.","vi":"Mỗi sinh viên được chỉ định một người hướng dẫn trong tuần đầu tiên."}]', '[{"phrase":"assign a task"},{"phrase":"assign responsibility"},{"phrase":"randomly assigned"}]', 'assign sth to sb / assign sb sth', '/əˈsaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assig/assign__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 7, 'attach', 'đính kèm; gắn', 'verb', '[{"en":"I have attached a copy of the report to this email.","vi":"Tôi đã đính kèm một bản sao báo cáo vào email này."},{"en":"Sensors were attached to the patients'' wrists to monitor their sleep.","vi":"Các cảm biến được gắn vào cổ tay bệnh nhân để theo dõi giấc ngủ."},{"en":"Please attach a recent photo to your application form.","vi":"Vui lòng đính kèm một ảnh gần đây vào đơn đăng ký của bạn."}]', '[{"phrase":"attach a file"},{"phrase":"attach a photo"},{"phrase":"attached to"}]', 'attach sth to sth', '/əˈtætʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 8, 'author', 'tác giả', 'noun', '[{"en":"The author of the study works at a university in Canada.","vi":"Tác giả của nghiên cứu làm việc tại một trường đại học ở Canada."},{"en":"Many authors now publish their books online.","vi":"Ngày nay nhiều tác giả xuất bản sách của họ trên mạng."},{"en":"According to the authors, the results need further testing.","vi":"Theo các tác giả, kết quả cần được kiểm chứng thêm."}]', '[{"phrase":"author of"},{"phrase":"lead author"},{"phrase":"best-selling author"}]', NULL, '/ˈɔːθər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autho/author__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 9, 'bond', 'mối gắn bó; liên kết; trái phiếu', 'noun', '[{"en":"Working through hard times together can create a strong bond between colleagues.","vi":"Cùng nhau vượt qua giai đoạn khó khăn có thể tạo nên sự gắn bó bền chặt giữa các đồng nghiệp."},{"en":"Energy is released when new chemical bonds form.","vi":"Năng lượng được giải phóng khi các liên kết hóa học mới hình thành."},{"en":"Investors moved their money from stocks into government bonds.","vi":"Các nhà đầu tư chuyển tiền từ cổ phiếu sang trái phiếu chính phủ."}]', '[{"phrase":"strong bond"},{"phrase":"chemical bond"},{"phrase":"government bonds"},{"phrase":"bond between"}]', NULL, '/bɑːnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bon/bond_/bond__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 10, 'brief', 'ngắn gọn; ngắn ngủi', 'adjective', '[{"en":"Please keep your answers brief and to the point.","vi":"Vui lòng trả lời ngắn gọn và đúng trọng tâm."},{"en":"After a brief introduction, the speaker moved on to the main findings.","vi":"Sau phần giới thiệu ngắn gọn, diễn giả chuyển sang những phát hiện chính."},{"en":"She made a brief visit to the factory last month.","vi":"Tháng trước cô ấy đã có một chuyến thăm ngắn đến nhà máy."}]', '[{"phrase":"brief introduction"},{"phrase":"brief summary"},{"phrase":"brief visit"},{"phrase":"keep it brief"}]', NULL, '/briːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brief/brief__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 11, 'capable', 'có khả năng; có năng lực', 'adjective', '[{"en":"The new system is capable of processing thousands of orders per hour.","vi":"Hệ thống mới có khả năng xử lý hàng nghìn đơn hàng mỗi giờ."},{"en":"She is a highly capable manager with years of experience.","vi":"Cô ấy là một nhà quản lý rất có năng lực với nhiều năm kinh nghiệm."},{"en":"Few animals are capable of recognizing themselves in a mirror.","vi":"Rất ít loài động vật có khả năng nhận ra chính mình trong gương."}]', '[{"phrase":"capable of"},{"phrase":"highly capable"},{"phrase":"perfectly capable"}]', 'capable of + V-ing / danh từ', '/ˈkeɪpəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capab/capable__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 12, 'cite', 'trích dẫn; viện dẫn, nêu ra', 'verb', '[{"en":"Always cite your sources at the end of an essay.","vi":"Hãy luôn trích dẫn nguồn tài liệu ở cuối bài luận."},{"en":"The paper is widely cited by researchers in the field.","vi":"Bài báo này được các nhà nghiên cứu trong ngành trích dẫn rộng rãi."},{"en":"Many workers cited low pay as their main reason for leaving.","vi":"Nhiều người lao động nêu mức lương thấp là lý do chính khiến họ nghỉ việc."}]', '[{"phrase":"cite a source"},{"phrase":"widely cited"},{"phrase":"frequently cited"},{"phrase":"cite an example"}]', 'cite sth as sth', '/saɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/cite_/cite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 13, 'cooperate', 'hợp tác; phối hợp', 'verb', '[{"en":"The two universities have agreed to cooperate on climate research.","vi":"Hai trường đại học đã đồng ý hợp tác trong nghiên cứu khí hậu."},{"en":"Several witnesses refused to cooperate with the police investigation.","vi":"Một số nhân chứng từ chối hợp tác với cuộc điều tra của cảnh sát."},{"en":"Departments must cooperate closely to finish the project on time.","vi":"Các phòng ban phải phối hợp chặt chẽ để hoàn thành dự án đúng hạn."}]', '[{"phrase":"cooperate with"},{"phrase":"cooperate closely"},{"phrase":"cooperate fully"},{"phrase":"agree to cooperate"}]', 'cooperate with sb on sth', '/kəʊˈɑːpəreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/coope/cooperate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 14, 'discriminate', 'phân biệt đối xử; phân biệt', 'verb', '[{"en":"It is illegal to discriminate against workers on the basis of age.","vi":"Phân biệt đối xử với người lao động dựa trên tuổi tác là bất hợp pháp."},{"en":"Some employers still discriminate against women with young children.","vi":"Một số nhà tuyển dụng vẫn phân biệt đối xử với phụ nữ có con nhỏ."},{"en":"Babies can discriminate between different sounds from a very early age.","vi":"Trẻ sơ sinh có thể phân biệt các âm thanh khác nhau từ rất sớm."}]', '[{"phrase":"discriminate against"},{"phrase":"discriminate between"},{"phrase":"unfairly discriminate"}]', 'discriminate against (phân biệt đối xử) ≠ discriminate between (phân biệt)', '/dɪˈskrɪmɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discr/discriminate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 15, 'display', 'trưng bày; hiển thị; biểu lộ', 'verb', '[{"en":"The museum displays tools used by farmers thousands of years ago.","vi":"Bảo tàng trưng bày những công cụ mà người nông dân sử dụng từ hàng nghìn năm trước."},{"en":"The screen at the station displays information about train delays.","vi":"Màn hình ở nhà ga hiển thị thông tin về các chuyến tàu bị trễ."},{"en":"Several patients displayed signs of stress during the test.","vi":"Một số bệnh nhân biểu lộ dấu hiệu căng thẳng trong quá trình kiểm tra."}]', '[{"phrase":"display information"},{"phrase":"display signs of"},{"phrase":"proudly display"}]', NULL, '/dɪˈspleɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/displ/display__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 16, 'diverse', 'đa dạng', 'adjective', '[{"en":"The city has one of the most diverse populations in the country.","vi":"Thành phố này có dân cư thuộc hàng đa dạng nhất cả nước."},{"en":"Our team includes people from diverse backgrounds.","vi":"Đội của chúng tôi gồm những người có xuất thân đa dạng."},{"en":"Tropical forests are home to a highly diverse range of plants.","vi":"Rừng nhiệt đới là nơi sinh sống của vô số loài thực vật vô cùng đa dạng."}]', '[{"phrase":"diverse backgrounds"},{"phrase":"diverse range"},{"phrase":"culturally diverse"},{"phrase":"diverse population"}]', NULL, '/daɪˈvɜːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/diver/diverse__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 17, 'domain', 'lĩnh vực; phạm vi; tên miền', 'noun', '[{"en":"Artificial intelligence is now used in almost every domain of science.","vi":"Trí tuệ nhân tạo hiện được sử dụng trong hầu hết mọi lĩnh vực khoa học."},{"en":"Many historical documents are now in the public domain.","vi":"Nhiều tài liệu lịch sử hiện nay đã thuộc phạm vi công cộng."},{"en":"The company registered a new domain name for its online store.","vi":"Công ty đã đăng ký một tên miền mới cho cửa hàng trực tuyến của mình."}]', '[{"phrase":"public domain"},{"phrase":"domain name"},{"phrase":"domain of"}]', 'in the public domain = thuộc phạm vi công cộng (không còn bản quyền)', '/dəʊˈmeɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domai/domain__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 18, 'edit', 'biên tập; chỉnh sửa', 'verb', '[{"en":"She edits a monthly journal on environmental science.","vi":"Bà ấy biên tập một tạp chí hằng tháng về khoa học môi trường."},{"en":"Please edit your essay carefully before you submit it.","vi":"Hãy chỉnh sửa bài luận cẩn thận trước khi nộp."},{"en":"The interview was heavily edited before it was broadcast.","vi":"Cuộc phỏng vấn đã bị cắt chỉnh nhiều trước khi được phát sóng."}]', '[{"phrase":"edit a book"},{"phrase":"edit a document"},{"phrase":"heavily edited"}]', NULL, '/ˈedɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/edit_/edit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 19, 'enhance', 'nâng cao; tăng cường', 'verb', '[{"en":"The new software will enhance the quality of online lessons.","vi":"Phần mềm mới sẽ nâng cao chất lượng các bài học trực tuyến."},{"en":"Regular exercise can enhance memory and concentration.","vi":"Tập thể dục thường xuyên có thể tăng cường trí nhớ và khả năng tập trung."},{"en":"The company hopes the award will enhance its reputation abroad.","vi":"Công ty hy vọng giải thưởng sẽ nâng cao danh tiếng của mình ở nước ngoài."}]', '[{"phrase":"enhance the quality"},{"phrase":"enhance performance"},{"phrase":"greatly enhance"}]', NULL, '/ɪnˈhæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enh/enhan/enhance__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 20, 'estate', 'bất động sản; điền trang; tài sản (để lại)', 'noun', '[{"en":"Real estate prices in the capital rose by ten percent last year.","vi":"Giá bất động sản ở thủ đô đã tăng mười phần trăm vào năm ngoái."},{"en":"The family owned a large estate in the countryside.","vi":"Gia đình đó từng sở hữu một điền trang lớn ở vùng nông thôn."},{"en":"He left his entire estate to a local charity.","vi":"Ông ấy để lại toàn bộ tài sản cho một tổ chức từ thiện địa phương."}]', '[{"phrase":"real estate"},{"phrase":"estate agent"},{"phrase":"large estate"}]', 'real estate = bất động sản; estate agent (Anh) = người môi giới nhà đất', '/ɪˈsteɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estat/estate__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 21, 'exceed', 'vượt quá; vượt', 'verb', '[{"en":"Sales this year have exceeded our expectations by a wide margin.","vi":"Doanh số năm nay đã vượt xa kỳ vọng của chúng tôi."},{"en":"Drivers who exceed the speed limit will be fined.","vi":"Những tài xế vượt quá tốc độ cho phép sẽ bị phạt."},{"en":"The cost of the project must not exceed two million dollars.","vi":"Chi phí của dự án không được vượt quá hai triệu đô la."}]', '[{"phrase":"exceed expectations"},{"phrase":"exceed the speed limit"},{"phrase":"far exceed"}]', NULL, '/ɪkˈsiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excee/exceed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 22, 'expert', 'chuyên gia', 'noun', '[{"en":"Experts predict that housing prices will continue to rise next year.","vi":"Các chuyên gia dự đoán giá nhà sẽ tiếp tục tăng trong năm tới."},{"en":"We asked an expert in tax law to review the contract.","vi":"Chúng tôi đã nhờ một chuyên gia về luật thuế xem xét hợp đồng."},{"en":"She is a leading expert on climate change.","vi":"Bà ấy là một chuyên gia hàng đầu về biến đổi khí hậu."}]', '[{"phrase":"leading expert"},{"phrase":"expert on"},{"phrase":"expert in"},{"phrase":"independent expert"}]', 'expert on/in sth', '/ˈekspɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/expert__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 23, 'explicit', 'rõ ràng; tường minh', 'adjective', '[{"en":"The instructions were explicit: no phones are allowed during the exam.","vi":"Hướng dẫn rất rõ ràng: không được dùng điện thoại trong giờ thi."},{"en":"The contract makes no explicit reference to overtime pay.","vi":"Hợp đồng không đề cập rõ ràng đến tiền làm thêm giờ."},{"en":"Teachers should make the learning goals explicit at the start of each lesson.","vi":"Giáo viên nên nêu rõ mục tiêu học tập ngay từ đầu mỗi bài học."}]', '[{"phrase":"explicit reference"},{"phrase":"explicit instructions"},{"phrase":"make explicit"}]', 'explicit (rõ ràng) ≠ implicit (ngầm)', '/ɪkˈsplɪsɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expli/explicit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 24, 'federal', '(thuộc) liên bang', 'adjective', '[{"en":"The project received funding from the federal government.","vi":"Dự án đã nhận được tài trợ từ chính phủ liên bang."},{"en":"Federal law requires employers to keep accurate records of working hours.","vi":"Luật liên bang yêu cầu người sử dụng lao động lưu giữ hồ sơ giờ làm việc chính xác."},{"en":"Germany and Australia both have a federal system of government.","vi":"Cả Đức và Úc đều có hệ thống chính quyền liên bang."}]', '[{"phrase":"federal government"},{"phrase":"federal law"},{"phrase":"federal agency"},{"phrase":"federal funding"}]', NULL, '/ˈfedərəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fed/feder/federal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 25, 'fee', 'phí; lệ phí; học phí', 'noun', '[{"en":"University fees have risen sharply over the past decade.","vi":"Học phí đại học đã tăng mạnh trong mười năm qua."},{"en":"There is a small fee for late registration.","vi":"Đăng ký muộn sẽ phải trả một khoản phí nhỏ."},{"en":"The lawyer charges a fixed fee for each consultation.","vi":"Luật sư tính một khoản phí cố định cho mỗi buổi tư vấn."}]', '[{"phrase":"pay a fee"},{"phrase":"charge a fee"},{"phrase":"tuition fees"},{"phrase":"fixed fee"}]', NULL, '/fiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/fee__/fee__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 26, 'flexible', 'linh hoạt; mềm dẻo, dễ uốn', 'adjective', '[{"en":"Many parents look for jobs with flexible working hours.","vi":"Nhiều bậc cha mẹ tìm những công việc có giờ làm việc linh hoạt."},{"en":"Our plans are flexible, so we can change the date if needed.","vi":"Kế hoạch của chúng tôi khá linh hoạt nên có thể đổi ngày nếu cần."},{"en":"The tube is made of a light, flexible plastic.","vi":"Chiếc ống được làm bằng loại nhựa nhẹ và dẻo."}]', '[{"phrase":"flexible working hours"},{"phrase":"flexible approach"},{"phrase":"highly flexible"}]', NULL, '/ˈfleksəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fle/flexi/flexible__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 27, 'furthermore', 'hơn nữa; ngoài ra', 'adverb', '[{"en":"The plan is expensive; furthermore, there is little evidence that it works.","vi":"Kế hoạch này tốn kém; hơn nữa, có rất ít bằng chứng cho thấy nó hiệu quả."},{"en":"Furthermore, it is unclear who will pay for the new system.","vi":"Ngoài ra, vẫn chưa rõ ai sẽ chi trả cho hệ thống mới."},{"en":"The new route is shorter and furthermore avoids the city center.","vi":"Tuyến đường mới ngắn hơn và hơn nữa còn tránh được trung tâm thành phố."}]', '[{"phrase":"and furthermore"},{"phrase":"furthermore, it is"}]', 'Dùng trong văn viết trang trọng, thường đứng đầu câu', '/ˌfɜːrðərˈmɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furth/furthermore__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 28, 'gender', 'giới tính; giới', 'noun', '[{"en":"Participants in the study were grouped by age and gender.","vi":"Những người tham gia nghiên cứu được phân nhóm theo độ tuổi và giới tính."},{"en":"The company is working to close the gender pay gap.","vi":"Công ty đang nỗ lực thu hẹp khoảng cách lương giữa các giới."},{"en":"The survey found no significant gender differences in reading habits.","vi":"Cuộc khảo sát không tìm thấy khác biệt đáng kể nào giữa các giới về thói quen đọc."}]', '[{"phrase":"gender equality"},{"phrase":"gender differences"},{"phrase":"gender pay gap"}]', NULL, '/ˈdʒendər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gende/gender__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 29, 'ignorant', 'thiếu hiểu biết; không biết', 'adjective', '[{"en":"Many consumers are ignorant of their legal rights.","vi":"Nhiều người tiêu dùng không biết về các quyền hợp pháp của mình."},{"en":"I felt completely ignorant during the discussion about tax law.","vi":"Tôi cảm thấy mình hoàn toàn thiếu hiểu biết trong cuộc thảo luận về luật thuế."},{"en":"The survey shows that the public remains largely ignorant about the new policy.","vi":"Khảo sát cho thấy phần lớn công chúng vẫn không biết gì về chính sách mới."}]', '[{"phrase":"ignorant of"},{"phrase":"ignorant about"},{"phrase":"completely ignorant"},{"phrase":"largely ignorant"}]', 'ignorant of/about sth; ignorant (adj) ≠ ignore (v: phớt lờ)', '/ˈɪɡnərənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ign/ignor/ignorant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-6-01', 30, 'incentive', 'động lực; sự khuyến khích; ưu đãi', 'noun', '[{"en":"The government offers tax incentives to companies that invest in clean energy.","vi":"Chính phủ đưa ra các ưu đãi thuế cho những công ty đầu tư vào năng lượng sạch."},{"en":"Workers have little incentive to stay late without extra pay.","vi":"Người lao động có rất ít động lực ở lại làm muộn nếu không được trả thêm tiền."},{"en":"Free meals were offered as an incentive to attend the training.","vi":"Bữa ăn miễn phí được đưa ra như một sự khuyến khích để tham gia buổi tập huấn."}]', '[{"phrase":"tax incentive"},{"phrase":"financial incentive"},{"phrase":"incentive to"},{"phrase":"provide an incentive"}]', 'incentive to do sth / incentive for sb', '/ɪnˈsentɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incen/incentive__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-7-01', 'awl-7', 'Học thuật Sublist 7 · Bộ 1', 'Academic Word List, sublist 7', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 1, 'adapt', 'thích nghi; điều chỉnh cho phù hợp', 'verb', '[{"en":"Many species have adapted to life in extremely cold climates.","vi":"Nhiều loài đã thích nghi với cuộc sống ở vùng khí hậu cực lạnh."},{"en":"Teachers often adapt their lessons for students with different needs.","vi":"Giáo viên thường điều chỉnh bài giảng cho phù hợp với học sinh có nhu cầu khác nhau."},{"en":"It took the new staff several weeks to adapt to the system.","vi":"Nhân viên mới mất vài tuần để thích nghi với hệ thống."}]', '[{"phrase":"adapt to"},{"phrase":"adapt quickly"},{"phrase":"adapt to change"}]', 'adapt to sth · adapt (thích nghi) ≠ adopt (áp dụng; nhận nuôi)', '/əˈdæpt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ada/adapt/adapt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 2, 'adult', 'người lớn; người trưởng thành', 'noun', '[{"en":"The course is designed for adults who want to return to education.","vi":"Khóa học được thiết kế cho những người lớn muốn quay lại việc học."},{"en":"Children under twelve must be accompanied by an adult.","vi":"Trẻ em dưới mười hai tuổi phải có người lớn đi kèm."},{"en":"The study followed a group of young adults for ten years.","vi":"Nghiên cứu đã theo dõi một nhóm thanh niên trong mười năm."}]', '[{"phrase":"young adult"},{"phrase":"adult education"},{"phrase":"adult population"}]', NULL, '/əˈdʌlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adu/adult/adult__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 3, 'advocate', 'ủng hộ; chủ trương; vận động cho', 'verb', '[{"en":"Many doctors advocate regular exercise as a way to reduce stress.","vi":"Nhiều bác sĩ ủng hộ việc tập thể dục thường xuyên như một cách giảm căng thẳng."},{"en":"The report advocates stronger rules on air pollution.","vi":"Bản báo cáo chủ trương siết chặt các quy định về ô nhiễm không khí."},{"en":"She has advocated for equal pay throughout her career.","vi":"Bà ấy đã vận động cho việc trả lương bình đẳng trong suốt sự nghiệp."}]', '[{"phrase":"strongly advocate"},{"phrase":"advocate for"},{"phrase":"advocate the use of"}]', 'Cũng là danh từ: người ủng hộ; luật sư biện hộ', '/ˈædvəkət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advoc/advocate__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 4, 'aid', 'viện trợ; sự trợ giúp', 'noun', '[{"en":"The country receives millions of dollars in foreign aid each year.","vi":"Quốc gia này nhận hàng triệu đô la viện trợ nước ngoài mỗi năm."},{"en":"Students from low-income families can apply for financial aid.","vi":"Sinh viên từ các gia đình thu nhập thấp có thể xin hỗ trợ tài chính."},{"en":"She learned the new language with the aid of an online course.","vi":"Cô ấy học ngôn ngữ mới với sự trợ giúp của một khóa học trực tuyến."}]', '[{"phrase":"foreign aid"},{"phrase":"financial aid"},{"phrase":"with the aid of"},{"phrase":"first aid"}]', NULL, '/eɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aid/aid__/aid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 5, 'channel', 'kênh; kênh truyền hình', 'noun', '[{"en":"Customers can contact the company through several channels, including email and live chat.","vi":"Khách hàng có thể liên hệ với công ty qua nhiều kênh, bao gồm email và trò chuyện trực tuyến."},{"en":"Complaints should be made through the proper channels.","vi":"Các khiếu nại cần được gửi qua đúng kênh quy định."},{"en":"The documentary will be shown on a public television channel next month.","vi":"Bộ phim tài liệu sẽ được chiếu trên một kênh truyền hình công cộng vào tháng tới."}]', '[{"phrase":"channels of communication"},{"phrase":"through the proper channels"},{"phrase":"television channel"}]', NULL, '/ˈtʃænl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chann/channel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 6, 'chemical', 'hóa chất', 'noun', '[{"en":"The factory was fined for releasing chemicals into the river.","vi":"Nhà máy bị phạt vì xả hóa chất ra sông."},{"en":"Farmers are using fewer harmful chemicals to protect their crops.","vi":"Nông dân đang sử dụng ít hóa chất độc hại hơn để bảo vệ cây trồng."},{"en":"Always store household chemicals out of the reach of children.","vi":"Luôn cất giữ các hóa chất gia dụng ngoài tầm với của trẻ em."}]', '[{"phrase":"toxic chemicals"},{"phrase":"harmful chemicals"},{"phrase":"household chemicals"}]', 'Tính từ chemical: (thuộc) hóa học, vd chemical reaction', '/ˈkemɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chemi/chemical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 7, 'classic', 'kinh điển; điển hình', 'adjective', '[{"en":"This is a classic example of how markets respond to fear.","vi":"Đây là một ví dụ điển hình về cách thị trường phản ứng trước nỗi sợ hãi."},{"en":"The book remains a classic study of urban poverty.","vi":"Cuốn sách vẫn là một nghiên cứu kinh điển về tình trạng nghèo đói ở đô thị."},{"en":"Headaches and tiredness are classic symptoms of dehydration.","vi":"Đau đầu và mệt mỏi là những triệu chứng điển hình của tình trạng mất nước."}]', '[{"phrase":"classic example"},{"phrase":"classic case"},{"phrase":"classic symptoms"}]', 'classic (kinh điển, điển hình) ≠ classical (cổ điển)', '/ˈklæsɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/classic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 8, 'comprehensive', 'toàn diện; bao quát; đầy đủ', 'adjective', '[{"en":"The authors provide a comprehensive review of research on sleep.","vi":"Các tác giả đưa ra một bài tổng quan toàn diện các nghiên cứu về giấc ngủ."},{"en":"All new employees receive comprehensive training during their first month.","vi":"Tất cả nhân viên mới đều được đào tạo đầy đủ trong tháng đầu tiên."},{"en":"We still lack a comprehensive plan for dealing with climate change.","vi":"Chúng ta vẫn chưa có một kế hoạch toàn diện để ứng phó với biến đổi khí hậu."}]', '[{"phrase":"comprehensive review"},{"phrase":"comprehensive study"},{"phrase":"comprehensive plan"}]', 'comprehensive (toàn diện) ≠ comprehensible (dễ hiểu)', '/ˌkɑːmprɪˈhensɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprehensive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 9, 'comprise', 'bao gồm; chiếm, cấu thành', 'verb', '[{"en":"The committee comprises twelve members from different departments.","vi":"Ủy ban gồm mười hai thành viên đến từ các phòng ban khác nhau."},{"en":"Women now comprise the majority of university students in many countries.","vi":"Ở nhiều nước, nữ giới hiện chiếm đa số sinh viên đại học."},{"en":"The survey comprised thirty questions about working conditions.","vi":"Bản khảo sát gồm ba mươi câu hỏi về điều kiện làm việc."}]', '[{"phrase":"comprise the majority of"},{"phrase":"be comprised of"}]', 'comprise + tân ngữ (không nói ''comprise of''); bị động: be comprised of', '/kəmˈpraɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 10, 'confirm', 'xác nhận; khẳng định', 'verb', '[{"en":"Please confirm your attendance at the meeting by Friday afternoon.","vi":"Vui lòng xác nhận việc bạn tham dự cuộc họp trước chiều thứ Sáu."},{"en":"The results confirm that the new drug is safe for adults.","vi":"Kết quả khẳng định rằng loại thuốc mới an toàn cho người lớn."},{"en":"Officials have not yet confirmed how many jobs will be cut.","vi":"Các quan chức vẫn chưa xác nhận sẽ có bao nhiêu việc làm bị cắt giảm."}]', '[{"phrase":"confirm that"},{"phrase":"officially confirm"},{"phrase":"confirm a booking"}]', NULL, '/kənˈfɜːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfirm__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 11, 'contrary', 'trái ngược; ngược lại', 'adjective', '[{"en":"Contrary to popular belief, most bats are not blind.","vi":"Trái với niềm tin phổ biến, phần lớn loài dơi không bị mù."},{"en":"The evidence was contrary to what the researchers had expected.","vi":"Bằng chứng trái ngược với những gì các nhà nghiên cứu đã dự đoán."},{"en":"The policy did not reduce costs; on the contrary, it increased them.","vi":"Chính sách này không giảm được chi phí; ngược lại, nó còn làm chi phí tăng lên."}]', '[{"phrase":"contrary to popular belief"},{"phrase":"on the contrary"},{"phrase":"contrary to expectations"}]', 'contrary to + N: trái với · on the contrary: ngược lại', '/ˈkɑːntreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 12, 'convert', 'chuyển đổi; biến đổi; cải tạo', 'verb', '[{"en":"Plants convert energy from sunlight into sugar that they can store.","vi":"Thực vật biến đổi năng lượng từ ánh sáng mặt trời thành đường để dự trữ."},{"en":"The old factory has been converted into student apartments.","vi":"Nhà máy cũ đã được cải tạo thành căn hộ cho sinh viên."},{"en":"You can easily convert the file to a PDF before sending it.","vi":"Bạn có thể dễ dàng chuyển tệp sang định dạng PDF trước khi gửi."}]', '[{"phrase":"convert into"},{"phrase":"convert energy"},{"phrase":"convert currency"}]', 'convert A into/to B', '/kənˈvɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvert__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 13, 'couple', 'cặp vợ chồng; cặp đôi; một vài', 'noun', '[{"en":"The study followed two hundred married couples over five years.","vi":"Nghiên cứu đã theo dõi hai trăm cặp vợ chồng trong năm năm."},{"en":"More young couples are choosing to delay having children.","vi":"Ngày càng nhiều cặp đôi trẻ chọn trì hoãn việc sinh con."},{"en":"The results should be available in a couple of weeks.","vi":"Kết quả sẽ có sau vài tuần nữa."}]', '[{"phrase":"married couple"},{"phrase":"young couple"},{"phrase":"a couple of"}]', NULL, '/ˈkʌpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/coupl/couple__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 14, 'decade', 'thập kỷ; mười năm', 'noun', '[{"en":"Global temperatures have risen steadily over the past three decades.","vi":"Nhiệt độ toàn cầu đã tăng đều đặn trong ba thập kỷ qua."},{"en":"The company has grown rapidly over the last decade.","vi":"Công ty đã phát triển nhanh chóng trong thập kỷ vừa qua."},{"en":"It may take decades to repair the damage to the forest.","vi":"Có thể phải mất hàng chục năm để khắc phục thiệt hại đối với khu rừng."}]', '[{"phrase":"past decade"},{"phrase":"over the last decade"},{"phrase":"for decades"}]', NULL, '/ˈdekeɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decad/decade__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 15, 'definite', 'rõ ràng, rõ rệt; chắc chắn, dứt khoát', 'adjective', '[{"en":"We need a definite answer before we can sign the contract.","vi":"Chúng tôi cần một câu trả lời dứt khoát trước khi có thể ký hợp đồng."},{"en":"There has been a definite improvement in the students'' writing this term.","vi":"Kỹ năng viết của học sinh đã tiến bộ rõ rệt trong học kỳ này."},{"en":"Nothing is definite yet, but the meeting will probably be on Monday.","vi":"Vẫn chưa có gì chắc chắn, nhưng cuộc họp có lẽ sẽ diễn ra vào thứ Hai."}]', '[{"phrase":"definite answer"},{"phrase":"definite improvement"},{"phrase":"definite plans"}]', 'definite (rõ ràng) ≠ definitive (cuối cùng, có tính quyết định)', '/ˈdefɪnət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/definite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 16, 'deny', 'phủ nhận; từ chối, không cho', 'verb', '[{"en":"The company denied that its products were unsafe.","vi":"Công ty phủ nhận việc sản phẩm của họ không an toàn."},{"en":"The manager strongly denied the claims made in the report.","vi":"Người quản lý kiên quyết phủ nhận những cáo buộc trong bản báo cáo."},{"en":"Students without an ID card were denied access to the library.","vi":"Sinh viên không có thẻ đã bị từ chối cho vào thư viện."}]', '[{"phrase":"strongly deny"},{"phrase":"deny access to"},{"phrase":"deny a claim"}]', 'deny + V-ing / that … · deny – denied – denied', '/dɪˈnaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/deny_/deny__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 17, 'differentiate', 'phân biệt; tạo sự khác biệt', 'verb', '[{"en":"Young children cannot always differentiate between fact and fiction.","vi":"Trẻ nhỏ không phải lúc nào cũng phân biệt được giữa sự thật và hư cấu."},{"en":"The test helps doctors differentiate one type of infection from another.","vi":"Xét nghiệm giúp bác sĩ phân biệt loại nhiễm trùng này với loại khác."},{"en":"Small firms need clear ways to differentiate themselves from larger competitors.","vi":"Các công ty nhỏ cần có cách rõ ràng để tạo sự khác biệt so với các đối thủ lớn hơn."}]', '[{"phrase":"differentiate between"},{"phrase":"differentiate from"},{"phrase":"clearly differentiate"}]', 'differentiate between A and B / A from B', '/ˌdɪfəˈrenʃieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/differentiate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 18, 'dispose', 'vứt bỏ; xử lý', 'verb', '[{"en":"Hospitals must safely dispose of used needles.","vi":"Bệnh viện phải xử lý an toàn kim tiêm đã qua sử dụng."},{"en":"The city is running out of places to dispose of waste.","vi":"Thành phố đang cạn dần nơi để xử lý rác thải."},{"en":"Please dispose of old batteries at a recycling center.","vi":"Vui lòng bỏ pin cũ tại trung tâm tái chế."}]', '[{"phrase":"dispose of waste"},{"phrase":"safely dispose of"}]', 'Luôn dùng dispose of + N', '/dɪˈspəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dispo/dispose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 19, 'dynamic', 'năng động; luôn vận động, biến đổi', 'adjective', '[{"en":"She is a dynamic leader who inspires her team.","vi":"Cô ấy là một nhà lãnh đạo năng động, truyền cảm hứng cho cả nhóm."},{"en":"The city has one of the most dynamic economies in the region.","vi":"Thành phố này có một trong những nền kinh tế năng động nhất khu vực."},{"en":"Learning a language is a dynamic process that continues throughout life.","vi":"Học ngôn ngữ là một quá trình luôn vận động và kéo dài suốt đời."}]', '[{"phrase":"dynamic leader"},{"phrase":"dynamic economy"},{"phrase":"dynamic process"}]', 'dynamics (n): sự tương tác, động lực, vd group dynamics', '/daɪˈnæmɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dyn/dynam/dynamic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 20, 'eliminate', 'loại bỏ; loại trừ; loại khỏi cuộc thi', 'verb', '[{"en":"The new system will eliminate the need for paper forms.","vi":"Hệ thống mới sẽ loại bỏ nhu cầu sử dụng biểu mẫu giấy."},{"en":"Doctors were able to eliminate several possible causes of the pain.","vi":"Các bác sĩ đã loại trừ được một số nguyên nhân có thể gây ra cơn đau."},{"en":"Our team was eliminated in the first round of the competition.","vi":"Đội chúng tôi đã bị loại ngay từ vòng đầu của cuộc thi."}]', '[{"phrase":"eliminate the need for"},{"phrase":"completely eliminate"},{"phrase":"eliminate poverty"}]', NULL, '/ɪˈlɪmɪneɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eli/elimi/eliminate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 21, 'empirical', 'thực nghiệm; dựa trên quan sát', 'adjective', '[{"en":"There is little empirical evidence to support this theory.","vi":"Có rất ít bằng chứng thực nghiệm ủng hộ lý thuyết này."},{"en":"The paper combines theory with a detailed empirical study of local markets.","vi":"Bài báo kết hợp lý thuyết với một nghiên cứu thực nghiệm chi tiết về các thị trường địa phương."},{"en":"Their conclusions are based on empirical data collected over ten years.","vi":"Kết luận của họ dựa trên dữ liệu thực nghiệm được thu thập trong mười năm."}]', '[{"phrase":"empirical evidence"},{"phrase":"empirical study"},{"phrase":"empirical data"},{"phrase":"empirical research"}]', NULL, '/ɪmˈpɪrɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empir/empirical__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 22, 'equip', 'trang bị', 'verb', '[{"en":"All classrooms are equipped with projectors and fast internet.","vi":"Tất cả phòng học đều được trang bị máy chiếu và internet tốc độ cao."},{"en":"The course aims to equip students with practical research skills.","vi":"Khóa học nhằm trang bị cho sinh viên các kỹ năng nghiên cứu thực tế."},{"en":"It will cost a lot of money to fully equip the new hospital.","vi":"Sẽ tốn rất nhiều tiền để trang bị đầy đủ cho bệnh viện mới."}]', '[{"phrase":"equipped with"},{"phrase":"equip students with"},{"phrase":"fully equip"},{"phrase":"well equipped"}]', 'equip – equipped – equipped · equip sb/sth with sth', '/ɪˈkwɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equip/equip__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 23, 'extract', 'chiết xuất; trích xuất; khai thác', 'verb', '[{"en":"Oil is extracted from the seeds and used in cooking.","vi":"Dầu được chiết xuất từ hạt và dùng để nấu ăn."},{"en":"The software can extract information from thousands of scanned documents.","vi":"Phần mềm có thể trích xuất thông tin từ hàng nghìn tài liệu đã quét."},{"en":"Mining companies extract large amounts of copper from the region every year.","vi":"Các công ty khai khoáng khai thác một lượng lớn đồng từ khu vực này mỗi năm."}]', '[{"phrase":"extract information"},{"phrase":"extract oil"},{"phrase":"extract data"}]', 'Danh từ extract: đoạn trích; tinh chất', '/ˈekstrækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extract__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 24, 'file', 'tệp; hồ sơ', 'noun', '[{"en":"Save the file before you close the program.","vi":"Hãy lưu tệp trước khi đóng chương trình."},{"en":"Doctors keep a file on every patient they treat.","vi":"Bác sĩ lưu hồ sơ về mỗi bệnh nhân mà họ điều trị."},{"en":"Please attach the file to your email and send it to the manager.","vi":"Vui lòng đính kèm tệp vào email và gửi cho người quản lý."}]', '[{"phrase":"save the file"},{"phrase":"attach the file"},{"phrase":"keep a file on"}]', 'Động từ file: nộp (đơn), lưu trữ, vd file a complaint', '/faɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/file_/file__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 25, 'finite', 'hữu hạn; có giới hạn', 'adjective', '[{"en":"Earth has a finite supply of oil and gas.","vi":"Trái Đất có nguồn cung dầu mỏ và khí đốt hữu hạn."},{"en":"We have finite resources, so we must choose our priorities carefully.","vi":"Chúng ta có nguồn lực hữu hạn, vì vậy phải lựa chọn ưu tiên một cách cẩn thận."},{"en":"There is only a finite number of places on the course.","vi":"Khóa học chỉ có một số lượng chỗ có hạn."}]', '[{"phrase":"finite resources"},{"phrase":"finite number"},{"phrase":"finite supply"}]', 'Trái nghĩa: infinite (vô hạn)', '/ˈfaɪnaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finit/finite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 26, 'foundation', 'nền tảng; cơ sở; quỹ', 'noun', '[{"en":"Good communication is the foundation of a successful team.","vi":"Giao tiếp tốt là nền tảng của một đội nhóm thành công."},{"en":"The first year provides a solid foundation in mathematics and statistics.","vi":"Năm đầu tiên cung cấp nền tảng vững chắc về toán học và thống kê."},{"en":"A local foundation offers scholarships to students from poor families.","vi":"Một quỹ địa phương cấp học bổng cho sinh viên từ các gia đình nghèo."}]', '[{"phrase":"solid foundation"},{"phrase":"lay the foundation for"},{"phrase":"charitable foundation"}]', NULL, '/faʊnˈdeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/foundation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 27, 'globe', 'địa cầu; thế giới; quả địa cầu', 'noun', '[{"en":"The company has offices in over forty countries across the globe.","vi":"Công ty có văn phòng tại hơn bốn mươi quốc gia trên khắp thế giới."},{"en":"Scientists from around the globe shared their findings at the conference.","vi":"Các nhà khoa học từ khắp nơi trên thế giới đã chia sẻ phát hiện của họ tại hội nghị."},{"en":"The teacher used a globe to show where each country is.","vi":"Giáo viên dùng quả địa cầu để chỉ vị trí của từng quốc gia."}]', '[{"phrase":"across the globe"},{"phrase":"around the globe"},{"phrase":"all over the globe"}]', 'Tính từ global: toàn cầu', '/ɡləʊb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/glo/globe/globe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 28, 'grade', 'điểm số; lớp; loại, cấp', 'noun', '[{"en":"She got the highest grade in the class on the final exam.","vi":"Cô ấy đạt điểm cao nhất lớp trong kỳ thi cuối kỳ."},{"en":"My son is in the fifth grade at a local school.","vi":"Con trai tôi đang học lớp năm ở một trường gần nhà."},{"en":"The factory only uses high-grade steel in its products.","vi":"Nhà máy chỉ sử dụng thép chất lượng cao cho sản phẩm của mình."}]', '[{"phrase":"good grades"},{"phrase":"in the fifth grade"},{"phrase":"high-grade"}]', 'Mỹ: grade = lớp (fifth grade) · Anh: year', '/ɡreɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grade/grade__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 29, 'guarantee', 'đảm bảo; bảo hành', 'verb', '[{"en":"A university degree no longer guarantees a well-paid job.","vi":"Bằng đại học không còn đảm bảo một công việc lương cao."},{"en":"We cannot guarantee that the results will be the same next year.","vi":"Chúng tôi không thể đảm bảo rằng kết quả năm sau sẽ giống như vậy."},{"en":"All our laptops are guaranteed for two years.","vi":"Tất cả máy tính xách tay của chúng tôi đều được bảo hành hai năm."}]', '[{"phrase":"guarantee success"},{"phrase":"cannot guarantee"},{"phrase":"guaranteed for"}]', 'Cũng là danh từ: sự bảo đảm; giấy bảo hành', '/ˌɡærənˈtiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gua/guara/guarantee__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-01', 30, 'hierarchy', 'hệ thống cấp bậc; thứ bậc', 'noun', '[{"en":"She quickly rose through the corporate hierarchy.","vi":"Cô ấy nhanh chóng thăng tiến trong hệ thống cấp bậc của công ty."},{"en":"Many traditional organizations have a strict hierarchy of managers and workers.","vi":"Nhiều tổ chức truyền thống có hệ thống cấp bậc chặt chẽ giữa quản lý và nhân viên."},{"en":"The model places basic needs such as food at the bottom of the hierarchy.","vi":"Mô hình này đặt các nhu cầu cơ bản như thức ăn ở tầng thấp nhất của hệ thống thứ bậc."}]', '[{"phrase":"strict hierarchy"},{"phrase":"social hierarchy"},{"phrase":"corporate hierarchy"}]', NULL, '/ˈhaɪərɑːrki/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hie/hiera/hierarchy__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-7-02', 'awl-7', 'Học thuật Sublist 7 · Bộ 2', 'Academic Word List, sublist 7', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 1, 'identical', 'giống hệt; y hệt', 'adjective', '[{"en":"The two samples were identical in size and chemical composition.","vi":"Hai mẫu giống hệt nhau về kích thước và thành phần hóa học."},{"en":"Both groups received identical instructions before the test began.","vi":"Cả hai nhóm đều nhận được hướng dẫn giống hệt nhau trước khi bài kiểm tra bắt đầu."},{"en":"Her results were almost identical to those of the earlier study.","vi":"Kết quả của cô ấy gần như giống hệt kết quả của nghiên cứu trước đó."}]', '[{"phrase":"almost identical"},{"phrase":"identical to"},{"phrase":"virtually identical"},{"phrase":"identical twins"}]', 'identical to sth', '/aɪˈdentɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identical__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 2, 'ideology', 'hệ tư tưởng; ý thức hệ', 'noun', '[{"en":"The book examines how ideology shapes the way people see the world.","vi":"Cuốn sách xem xét cách hệ tư tưởng định hình cách con người nhìn nhận thế giới."},{"en":"Researchers should not let personal ideology influence their findings.","vi":"Các nhà nghiên cứu không nên để hệ tư tưởng cá nhân chi phối kết quả nghiên cứu."},{"en":"Every society has a dominant ideology that few people openly question.","vi":"Mỗi xã hội đều có một hệ tư tưởng chủ đạo mà ít người công khai đặt câu hỏi."}]', '[{"phrase":"dominant ideology"},{"phrase":"political ideology"},{"phrase":"ideology of"}]', NULL, '/ˌaɪdiˈɑːlədʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ideol/ideology__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 3, 'infer', 'suy ra; suy luận', 'verb', '[{"en":"From these results, we can infer that the drug is safe for adults.","vi":"Từ những kết quả này, chúng ta có thể suy ra rằng thuốc an toàn cho người lớn."},{"en":"Readers must infer the writer''s opinion from the tone of the article.","vi":"Người đọc phải suy ra quan điểm của tác giả từ giọng điệu của bài báo."},{"en":"Scientists inferred the age of the rocks from the fossils found inside.","vi":"Các nhà khoa học đã suy ra tuổi của những tảng đá từ các hóa thạch tìm thấy bên trong."}]', '[{"phrase":"infer from"},{"phrase":"infer that"},{"phrase":"reasonably infer"}]', 'infer sth from sth · infer – inferred – inferred', '/ɪnˈfɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infer/infer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 4, 'innovate', 'đổi mới; cải tiến', 'verb', '[{"en":"Companies that fail to innovate often lose customers to their competitors.","vi":"Những công ty không đổi mới thường mất khách hàng vào tay đối thủ cạnh tranh."},{"en":"Small firms can often innovate faster than large organizations.","vi":"Các công ty nhỏ thường có thể đổi mới nhanh hơn các tổ chức lớn."},{"en":"Farmers in the region are innovating to cope with less rainfall.","vi":"Nông dân trong vùng đang đổi mới cách làm để thích ứng với lượng mưa ít hơn."}]', '[{"phrase":"fail to innovate"},{"phrase":"ability to innovate"},{"phrase":"continue to innovate"}]', NULL, '/ˈɪnəveɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/innov/innovate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 5, 'insert', 'chèn; đưa vào, cho vào', 'verb', '[{"en":"Please insert a short summary at the beginning of the report.","vi":"Vui lòng chèn một bản tóm tắt ngắn vào đầu báo cáo."},{"en":"Insert your card into the machine and enter your code.","vi":"Hãy cho thẻ của bạn vào máy và nhập mã."},{"en":"The doctor carefully inserted a thin tube into the patient''s arm.","vi":"Bác sĩ cẩn thận đưa một ống nhỏ vào cánh tay bệnh nhân."}]', '[{"phrase":"insert into"},{"phrase":"insert a card"},{"phrase":"insert a clause"}]', 'insert sth into sth', '/ɪnˈsɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inser/insert__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 6, 'intervene', 'can thiệp; xen vào', 'verb', '[{"en":"The central bank intervened to stop the currency from falling further.","vi":"Ngân hàng trung ương đã can thiệp để ngăn đồng tiền tiếp tục mất giá."},{"en":"Teachers should intervene early when a child is having trouble reading.","vi":"Giáo viên nên can thiệp sớm khi một đứa trẻ gặp khó khăn trong việc đọc."},{"en":"The manager had to intervene in a dispute between two staff members.","vi":"Người quản lý đã phải can thiệp vào một cuộc tranh chấp giữa hai nhân viên."}]', '[{"phrase":"intervene in"},{"phrase":"intervene early"},{"phrase":"decide to intervene"}]', 'intervene in sth', '/ˌɪntərˈviːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/intervene__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 7, 'isolate', 'cô lập; cách ly; tách riêng', 'verb', '[{"en":"Patients with the virus were isolated from others in the hospital.","vi":"Những bệnh nhân nhiễm virus đã được cách ly khỏi những người khác trong bệnh viện."},{"en":"Scientists managed to isolate the gene responsible for the disease.","vi":"Các nhà khoa học đã tách được gen gây ra căn bệnh này."},{"en":"Working from home can isolate employees from their colleagues.","vi":"Làm việc tại nhà có thể khiến nhân viên bị cô lập khỏi đồng nghiệp."}]', '[{"phrase":"isolate from"},{"phrase":"isolate a gene"},{"phrase":"become isolated"}]', 'isolate sb/sth from sb/sth', '/ˈaɪsəleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iso/isola/isolate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 8, 'media', 'truyền thông; phương tiện truyền thông', 'noun', '[{"en":"The study received a lot of attention in the media.","vi":"Nghiên cứu này nhận được nhiều sự chú ý trên truyền thông."},{"en":"Social media has changed the way young people get news.","vi":"Mạng xã hội đã thay đổi cách giới trẻ tiếp nhận tin tức."},{"en":"The company refused to comment when contacted by the media.","vi":"Công ty đã từ chối bình luận khi được giới truyền thông liên hệ."}]', '[{"phrase":"social media"},{"phrase":"mass media"},{"phrase":"media coverage"},{"phrase":"news media"}]', 'số nhiều của medium; thường đi với động từ số ít', '/ˈmiːdiə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/media/media__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 9, 'mode', 'phương thức; chế độ', 'noun', '[{"en":"Buses remain the most common mode of transport in the city.","vi":"Xe buýt vẫn là phương thức di chuyển phổ biến nhất trong thành phố."},{"en":"Switch the camera to night mode before taking the photo.","vi":"Hãy chuyển máy ảnh sang chế độ ban đêm trước khi chụp ảnh."},{"en":"Many universities moved to an online mode of teaching during the crisis.","vi":"Nhiều trường đại học đã chuyển sang phương thức giảng dạy trực tuyến trong thời kỳ khủng hoảng."}]', '[{"phrase":"mode of transport"},{"phrase":"mode of communication"},{"phrase":"mode of delivery"}]', NULL, '/məʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/mode_/mode__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 10, 'paradigm', 'mô hình; hệ hình', 'noun', '[{"en":"The discovery led to a paradigm shift in modern physics.","vi":"Phát hiện này đã dẫn đến một sự chuyển đổi mô hình trong vật lý hiện đại."},{"en":"The new theory challenged the dominant paradigm in economics.","vi":"Lý thuyết mới đã thách thức hệ hình thống trị trong kinh tế học."},{"en":"Online learning is not simply a new tool but a new paradigm.","vi":"Học trực tuyến không chỉ đơn giản là một công cụ mới mà là một mô hình mới."}]', '[{"phrase":"paradigm shift"},{"phrase":"dominant paradigm"},{"phrase":"new paradigm"}]', NULL, '/ˈpærədaɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parad/paradigm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 11, 'phenomenon', 'hiện tượng', 'noun', '[{"en":"Global warming is a phenomenon that affects every part of the planet.","vi":"Nóng lên toàn cầu là một hiện tượng ảnh hưởng đến mọi nơi trên hành tinh."},{"en":"Scientists still cannot fully explain this natural phenomenon.","vi":"Các nhà khoa học vẫn chưa thể giải thích đầy đủ hiện tượng tự nhiên này."},{"en":"Similar phenomena have been observed in several other large cities.","vi":"Những hiện tượng tương tự đã được ghi nhận ở một số thành phố lớn khác."}]', '[{"phrase":"natural phenomenon"},{"phrase":"social phenomenon"},{"phrase":"explain a phenomenon"}]', 'số nhiều: phenomena', '/fəˈnɑːmɪnən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phe/pheno/phenomenon__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 12, 'priority', 'sự ưu tiên; điều ưu tiên', 'noun', '[{"en":"Patient safety must always be our top priority.","vi":"An toàn của bệnh nhân phải luôn là ưu tiên hàng đầu của chúng ta."},{"en":"The government has made education reform a priority this year.","vi":"Chính phủ đã đặt cải cách giáo dục làm ưu tiên trong năm nay."},{"en":"Families with young children are given priority for housing.","vi":"Các gia đình có con nhỏ được ưu tiên về nhà ở."}]', '[{"phrase":"top priority"},{"phrase":"high priority"},{"phrase":"give priority to"},{"phrase":"set priorities"}]', NULL, '/praɪˈɔːrəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/priority__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 13, 'prohibit', 'cấm', 'verb', '[{"en":"The law prohibits companies from selling personal data without consent.","vi":"Luật cấm các công ty bán dữ liệu cá nhân khi không có sự đồng ý."},{"en":"Smoking is strictly prohibited inside the building.","vi":"Hút thuốc bị nghiêm cấm bên trong tòa nhà."},{"en":"Many schools now prohibit the use of phones during lessons.","vi":"Nhiều trường học hiện nay cấm sử dụng điện thoại trong giờ học."}]', '[{"phrase":"strictly prohibited"},{"phrase":"prohibit the use of"},{"phrase":"prohibit sb from doing sth"}]', 'prohibit sb from doing sth', '/prəˈhɪbɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prohi/prohibit__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 14, 'publication', 'sự xuất bản, công bố; ấn phẩm', 'noun', '[{"en":"The article was accepted for publication in a leading medical journal.","vi":"Bài báo đã được chấp nhận để đăng trên một tạp chí y khoa hàng đầu."},{"en":"The report has been delayed, and publication is now expected next month.","vi":"Báo cáo đã bị hoãn, và việc công bố hiện được dự kiến vào tháng tới."},{"en":"The library keeps copies of all the university''s official publications.","vi":"Thư viện lưu giữ bản sao của tất cả các ấn phẩm chính thức của trường đại học."}]', '[{"phrase":"accepted for publication"},{"phrase":"publication date"},{"phrase":"scientific publication"}]', NULL, '/ˌpʌblɪˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publication__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 15, 'quote', 'trích dẫn; báo giá', 'verb', '[{"en":"The author quotes several experts to support her main argument.","vi":"Tác giả trích dẫn một số chuyên gia để củng cố lập luận chính của mình."},{"en":"Students must use quotation marks when they quote directly from a source.","vi":"Sinh viên phải dùng dấu ngoặc kép khi trích dẫn trực tiếp từ một nguồn."},{"en":"The builder quoted us a price of two thousand dollars for the repairs.","vi":"Người thợ xây đã báo giá cho chúng tôi hai nghìn đô la cho việc sửa chữa."}]', '[{"phrase":"quote from"},{"phrase":"quote directly"},{"phrase":"quote a price"},{"phrase":"widely quoted"}]', NULL, '/kwəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/quo/quote/quote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 16, 'release', 'công bố, phát hành; giải phóng, thả ra', 'verb', '[{"en":"The ministry will release the full report next week.","vi":"Bộ sẽ công bố toàn bộ báo cáo vào tuần tới."},{"en":"The company released a new version of its software on Monday.","vi":"Công ty đã phát hành phiên bản mới của phần mềm vào thứ Hai."},{"en":"Burning coal releases large amounts of carbon dioxide into the air.","vi":"Việc đốt than giải phóng một lượng lớn khí carbon dioxide vào không khí."}]', '[{"phrase":"release a report"},{"phrase":"release figures"},{"phrase":"release energy"}]', NULL, '/rɪˈliːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relea/release__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 17, 'reverse', 'đảo ngược; lật ngược', 'verb', '[{"en":"The court reversed the earlier decision after reviewing new evidence.","vi":"Tòa án đã lật ngược quyết định trước đó sau khi xem xét bằng chứng mới."},{"en":"It may take decades to reverse the damage to the forest.","vi":"Có thể phải mất hàng chục năm mới đảo ngược được những tổn hại đối với khu rừng."},{"en":"If we reverse the order of the questions, do the answers change?","vi":"Nếu chúng ta đảo ngược thứ tự các câu hỏi, câu trả lời có thay đổi không?"}]', '[{"phrase":"reverse a decision"},{"phrase":"reverse the trend"},{"phrase":"reverse the order"}]', NULL, '/rɪˈvɜːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/rever/reverse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 18, 'simulate', 'mô phỏng', 'verb', '[{"en":"The software simulates how the virus spreads through a population.","vi":"Phần mềm mô phỏng cách virus lây lan trong cộng đồng dân cư."},{"en":"Pilots train in machines that simulate real flight conditions.","vi":"Phi công được huấn luyện trong các thiết bị mô phỏng điều kiện bay thực tế."},{"en":"We simulated a power failure to test the backup system.","vi":"Chúng tôi đã mô phỏng một sự cố mất điện để kiểm tra hệ thống dự phòng."}]', '[{"phrase":"simulate conditions"},{"phrase":"simulate the effects of"}]', NULL, '/ˈsɪmjuleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simul/simulate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 19, 'sole', 'duy nhất; độc quyền', 'adjective', '[{"en":"Tourism is the sole source of income for many families on the island.","vi":"Du lịch là nguồn thu nhập duy nhất của nhiều gia đình trên đảo."},{"en":"The publisher has sole rights to the book in Asia.","vi":"Nhà xuất bản nắm độc quyền đối với cuốn sách tại châu Á."},{"en":"The sole purpose of the meeting was to agree on a budget.","vi":"Mục đích duy nhất của cuộc họp là thống nhất ngân sách."}]', '[{"phrase":"sole purpose"},{"phrase":"sole source"},{"phrase":"sole responsibility"},{"phrase":"sole owner"}]', NULL, '/səʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/sole_/sole__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 20, 'somewhat', 'hơi; phần nào', 'adverb', '[{"en":"The results were somewhat different from what we had expected.","vi":"Kết quả hơi khác so với những gì chúng tôi đã dự đoán."},{"en":"Prices have fallen somewhat since the start of the year.","vi":"Giá cả đã giảm phần nào kể từ đầu năm."},{"en":"I found the second half of the lecture somewhat confusing.","vi":"Tôi thấy nửa sau của bài giảng hơi khó hiểu."}]', '[{"phrase":"somewhat different"},{"phrase":"somewhat surprising"},{"phrase":"somewhat similar"}]', NULL, '/ˈsʌmwʌt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somew/somewhat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 21, 'submit', 'nộp; đệ trình', 'verb', '[{"en":"All assignments must be submitted online by Friday at noon.","vi":"Tất cả bài tập phải được nộp trực tuyến trước trưa thứ Sáu."},{"en":"The committee submitted its final report to the board last month.","vi":"Ủy ban đã đệ trình báo cáo cuối cùng lên hội đồng quản trị vào tháng trước."},{"en":"Have you submitted your application for the scholarship yet?","vi":"Bạn đã nộp hồ sơ xin học bổng chưa?"}]', '[{"phrase":"submit an application"},{"phrase":"submit a report"},{"phrase":"submit to"}]', 'submit – submitted – submitted', '/səbˈmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/submi/submit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 22, 'successor', 'người kế nhiệm; người/vật kế tiếp', 'noun', '[{"en":"The director will retire next year, but no successor has been chosen.","vi":"Giám đốc sẽ nghỉ hưu vào năm sau, nhưng vẫn chưa chọn được người kế nhiệm."},{"en":"The board appointed her as successor to the chief executive.","vi":"Hội đồng quản trị đã bổ nhiệm bà ấy làm người kế nhiệm tổng giám đốc."},{"en":"The new phone is a worthy successor to last year''s model.","vi":"Chiếc điện thoại mới là sản phẩm kế tiếp xứng đáng của mẫu năm ngoái."}]', '[{"phrase":"successor to"},{"phrase":"worthy successor"},{"phrase":"natural successor"},{"phrase":"name a successor"}]', 'successor to sb/sth', '/səkˈsesər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/successor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 23, 'survive', 'sống sót; tồn tại', 'verb', '[{"en":"Only a few small businesses survived the economic crisis.","vi":"Chỉ một vài doanh nghiệp nhỏ tồn tại được qua cuộc khủng hoảng kinh tế."},{"en":"These plants can survive for months without much water.","vi":"Những loài cây này có thể sống sót hàng tháng mà không cần nhiều nước."},{"en":"Very few documents from that period have survived.","vi":"Rất ít tài liệu từ thời kỳ đó còn tồn tại đến nay."}]', '[{"phrase":"survive a crisis"},{"phrase":"manage to survive"},{"phrase":"struggle to survive"}]', NULL, '/sərˈvaɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/survi/survive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 24, 'thesis', 'luận văn, luận án; luận điểm', 'noun', '[{"en":"She is writing her master''s thesis on climate policy.","vi":"Cô ấy đang viết luận văn thạc sĩ về chính sách khí hậu."},{"en":"He spent four years working on his doctoral thesis.","vi":"Anh ấy đã dành bốn năm để thực hiện luận án tiến sĩ của mình."},{"en":"The central thesis of the book is that cities drive economic growth.","vi":"Luận điểm trung tâm của cuốn sách là các thành phố thúc đẩy tăng trưởng kinh tế."}]', '[{"phrase":"master''s thesis"},{"phrase":"doctoral thesis"},{"phrase":"central thesis"}]', 'số nhiều: theses', '/ˈθiːsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/thesi/thesis__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 25, 'topic', 'chủ đề; đề tài', 'noun', '[{"en":"Climate change is a popular topic for student research projects.","vi":"Biến đổi khí hậu là một đề tài phổ biến cho các dự án nghiên cứu của sinh viên."},{"en":"Let''s move on to the next topic on the agenda.","vi":"Chúng ta hãy chuyển sang chủ đề tiếp theo trong chương trình họp."},{"en":"Mental health has become a major topic of discussion in schools.","vi":"Sức khỏe tinh thần đã trở thành một chủ đề thảo luận lớn trong các trường học."}]', '[{"phrase":"topic of discussion"},{"phrase":"main topic"},{"phrase":"choose a topic"},{"phrase":"research topic"}]', NULL, '/ˈtɑːpɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/top/topic/topic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 26, 'transmit', 'truyền; lây truyền', 'verb', '[{"en":"Satellites transmit signals back to stations on Earth.","vi":"Các vệ tinh truyền tín hiệu trở lại các trạm trên Trái Đất."},{"en":"The virus is transmitted mainly through close contact with infected people.","vi":"Virus lây truyền chủ yếu qua tiếp xúc gần với người bị nhiễm."},{"en":"Parents often transmit their values to their children without realizing it.","vi":"Cha mẹ thường truyền lại các giá trị của mình cho con cái mà không nhận ra."}]', '[{"phrase":"transmit a signal"},{"phrase":"transmit data"},{"phrase":"transmit a disease"}]', 'transmit – transmitted – transmitted', '/trænzˈmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transmit__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 27, 'ultimate', 'cuối cùng; cơ bản, sâu xa', 'adjective', '[{"en":"Our ultimate goal is to make the service free for all students.","vi":"Mục tiêu cuối cùng của chúng tôi là cung cấp dịch vụ miễn phí cho tất cả sinh viên."},{"en":"The ultimate decision rests with the board of directors.","vi":"Quyết định cuối cùng thuộc về hội đồng quản trị."},{"en":"The ultimate cause of the problem was poor communication between teams.","vi":"Nguyên nhân sâu xa của vấn đề là sự giao tiếp kém giữa các nhóm."}]', '[{"phrase":"ultimate goal"},{"phrase":"ultimate aim"},{"phrase":"ultimate responsibility"}]', NULL, '/ˈʌltɪmət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ult/ultim/ultimate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 28, 'unique', 'duy nhất, riêng biệt; độc đáo', 'adjective', '[{"en":"Each participant was given a unique identification number.","vi":"Mỗi người tham gia được cấp một mã số nhận dạng riêng."},{"en":"The island is home to many plants that are unique to the region.","vi":"Hòn đảo là nơi sinh sống của nhiều loài thực vật chỉ có ở khu vực này."},{"en":"The museum offers visitors a unique opportunity to see ancient writing.","vi":"Bảo tàng mang đến cho du khách một cơ hội có một không hai để xem chữ viết cổ."}]', '[{"phrase":"unique to"},{"phrase":"unique opportunity"},{"phrase":"unique feature"}]', 'unique to sth', '/juˈniːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/uniqu/unique__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 29, 'visible', 'có thể nhìn thấy; rõ ràng', 'adjective', '[{"en":"The mountains are clearly visible from the roof of the building.","vi":"Có thể nhìn thấy rõ những ngọn núi từ nóc tòa nhà."},{"en":"Some stars are not visible to the naked eye.","vi":"Một số ngôi sao không thể nhìn thấy bằng mắt thường."},{"en":"The effects of the new policy are already visible in the data.","vi":"Tác động của chính sách mới đã thể hiện rõ trong số liệu."}]', '[{"phrase":"clearly visible"},{"phrase":"visible to the naked eye"},{"phrase":"highly visible"},{"phrase":"visible from"}]', NULL, '/ˈvɪzəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visib/visible__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-7-02', 30, 'voluntary', 'tự nguyện; tình nguyện', 'adjective', '[{"en":"Taking part in the survey is completely voluntary.","vi":"Việc tham gia khảo sát là hoàn toàn tự nguyện."},{"en":"She does voluntary work at a local hospital on weekends.","vi":"Cô ấy làm công việc tình nguyện tại một bệnh viện địa phương vào cuối tuần."},{"en":"Many firms have signed a voluntary agreement to cut plastic waste.","vi":"Nhiều công ty đã ký một thỏa thuận tự nguyện nhằm cắt giảm rác thải nhựa."}]', '[{"phrase":"voluntary work"},{"phrase":"on a voluntary basis"},{"phrase":"completely voluntary"}]', NULL, '/ˈvɑːlənteri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volun/voluntary__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-8-01', 'awl-8', 'Học thuật Sublist 8 · Bộ 1', 'Academic Word List, sublist 8', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 1, 'abandon', 'từ bỏ; bỏ rơi; bỏ lại', 'verb', '[{"en":"The company abandoned the project after costs rose sharply.","vi":"Công ty đã từ bỏ dự án sau khi chi phí tăng mạnh."},{"en":"Many farmers were forced to abandon their land during the drought.","vi":"Nhiều nông dân buộc phải bỏ lại đất đai của mình trong đợt hạn hán."},{"en":"Researchers should not abandon a theory simply because one test failed.","vi":"Các nhà nghiên cứu không nên từ bỏ một lý thuyết chỉ vì một thử nghiệm thất bại."}]', '[{"phrase":"abandon a plan"},{"phrase":"abandon a project"},{"phrase":"abandon an attempt"}]', NULL, '/əˈbændən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aba/aband/abandon__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 2, 'accompany', 'đi kèm; đi cùng', 'verb', '[{"en":"Children under twelve must be accompanied by an adult.","vi":"Trẻ em dưới mười hai tuổi phải có người lớn đi cùng."},{"en":"Each chart is accompanied by a short explanation of the data.","vi":"Mỗi biểu đồ đều đi kèm một lời giải thích ngắn về dữ liệu."},{"en":"Rapid economic growth is often accompanied by rising prices.","vi":"Tăng trưởng kinh tế nhanh thường đi kèm với giá cả tăng."}]', '[{"phrase":"be accompanied by"},{"phrase":"accompanying text"},{"phrase":"accompanied by an adult"}]', 'thường dùng bị động: be accompanied by', '/əˈkʌmpəni/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accompany__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 3, 'accumulate', 'tích lũy; tích tụ', 'verb', '[{"en":"Over ten years, the family accumulated enough savings to buy a house.","vi":"Trong mười năm, gia đình đó đã tích lũy đủ tiền tiết kiệm để mua nhà."},{"en":"Dust and dirt accumulate quickly inside the machine.","vi":"Bụi bẩn tích tụ rất nhanh bên trong máy."},{"en":"Scientists have accumulated strong evidence that the climate is changing.","vi":"Các nhà khoa học đã tích lũy được bằng chứng rõ ràng rằng khí hậu đang thay đổi."}]', '[{"phrase":"accumulate wealth"},{"phrase":"accumulate evidence"},{"phrase":"accumulate data"}]', NULL, '/əˈkjuːmjəleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accum/accumulate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 4, 'ambiguous', 'mơ hồ; không rõ ràng; nước đôi', 'adjective', '[{"en":"The wording of the contract is ambiguous and needs to be revised.","vi":"Cách diễn đạt trong hợp đồng không rõ ràng và cần được sửa lại."},{"en":"Some survey questions were ambiguous, so participants interpreted them differently.","vi":"Một số câu hỏi khảo sát mơ hồ nên người tham gia hiểu chúng theo những cách khác nhau."},{"en":"The results of the study remain ambiguous.","vi":"Kết quả của nghiên cứu vẫn còn chưa rõ ràng."}]', '[{"phrase":"ambiguous language"},{"phrase":"highly ambiguous"},{"phrase":"ambiguous results"}]', NULL, '/æmˈbɪɡjuəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/amb/ambig/ambiguous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 5, 'append', 'thêm vào cuối; đính kèm', 'verb', '[{"en":"A full list of references is appended to the report.","vi":"Danh sách đầy đủ tài liệu tham khảo được đính kèm ở cuối báo cáo."},{"en":"A short summary is appended at the end of each chapter.","vi":"Một bản tóm tắt ngắn được thêm vào cuối mỗi chương."},{"en":"The program appends new data to the end of the file.","vi":"Chương trình thêm dữ liệu mới vào cuối tệp."}]', '[{"phrase":"append to"},{"phrase":"append a note"}]', 'append something to something', '/əˈpend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appen/append__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 6, 'appreciate', 'đánh giá cao; cảm kích; hiểu rõ', 'verb', '[{"en":"We really appreciate your help with the conference.","vi":"Chúng tôi thực sự cảm kích sự giúp đỡ của bạn cho hội nghị."},{"en":"Managers failed to appreciate how serious the problem was.","vi":"Các nhà quản lý đã không hiểu rõ vấn đề nghiêm trọng đến mức nào."},{"en":"Her colleagues greatly appreciated her careful approach to research.","vi":"Các đồng nghiệp đánh giá rất cao cách làm nghiên cứu cẩn thận của cô ấy."}]', '[{"phrase":"greatly appreciate"},{"phrase":"really appreciate"},{"phrase":"fully appreciate"}]', NULL, '/əˈpriːʃieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appre/appreciate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 7, 'arbitrary', 'tùy tiện; tùy ý; độc đoán', 'adjective', '[{"en":"The choice of sample size seemed arbitrary to the reviewers.","vi":"Việc chọn cỡ mẫu có vẻ tùy tiện đối với những người phản biện."},{"en":"Workers complained about arbitrary decisions made by their managers.","vi":"Công nhân phàn nàn về những quyết định độc đoán của quản lý."},{"en":"The boundary between the two categories is somewhat arbitrary.","vi":"Ranh giới giữa hai nhóm này phần nào mang tính tùy ý."}]', '[{"phrase":"arbitrary decision"},{"phrase":"arbitrary rules"},{"phrase":"somewhat arbitrary"}]', NULL, '/ˈɑːrbɪtreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arb/arbit/arbitrary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 8, 'automate', 'tự động hóa', 'verb', '[{"en":"The bank has automated most of its customer services.","vi":"Ngân hàng đã tự động hóa phần lớn các dịch vụ khách hàng."},{"en":"Many factory jobs could be automated within the next decade.","vi":"Nhiều công việc trong nhà máy có thể được tự động hóa trong thập kỷ tới."},{"en":"We use software to automate the process of checking invoices.","vi":"Chúng tôi dùng phần mềm để tự động hóa quy trình kiểm tra hóa đơn."}]', '[{"phrase":"automate a process"},{"phrase":"automate tasks"},{"phrase":"fully automated"}]', NULL, '/ˈɔːtəmeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autom/automate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 9, 'bias', 'thành kiến; thiên vị; sai lệch', 'noun', '[{"en":"The study was criticized for its bias toward urban schools.","vi":"Nghiên cứu bị chỉ trích vì thiên vị các trường học ở thành thị."},{"en":"Researchers took steps to reduce bias in the sample.","vi":"Các nhà nghiên cứu đã thực hiện các bước để giảm sai lệch trong mẫu."},{"en":"Employers must avoid gender bias when hiring new staff.","vi":"Nhà tuyển dụng phải tránh thành kiến giới tính khi tuyển nhân viên mới."}]', '[{"phrase":"gender bias"},{"phrase":"bias against"},{"phrase":"reduce bias"},{"phrase":"political bias"}]', 'bias against/toward(s) somebody', '/ˈbaɪəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bia/bias_/bias__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 10, 'chart', 'biểu đồ; bảng', 'noun', '[{"en":"The chart shows how prices changed over the past five years.","vi":"Biểu đồ cho thấy giá cả đã thay đổi như thế nào trong năm năm qua."},{"en":"Students were asked to present their results in a bar chart.","vi":"Sinh viên được yêu cầu trình bày kết quả dưới dạng biểu đồ cột."},{"en":"Nurses record each patient''s temperature on a chart.","vi":"Y tá ghi nhiệt độ của từng bệnh nhân vào một bảng theo dõi."}]', '[{"phrase":"bar chart"},{"phrase":"pie chart"},{"phrase":"the chart shows"}]', NULL, '/tʃɑːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chart/chart__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 11, 'clarify', 'làm rõ; giải thích rõ', 'verb', '[{"en":"Could you clarify what you mean by that term?","vi":"Bạn có thể làm rõ ý bạn muốn nói với thuật ngữ đó không?"},{"en":"The new guidelines clarify the rules for working from home.","vi":"Hướng dẫn mới làm rõ các quy định về làm việc tại nhà."},{"en":"The manager called a meeting to clarify the team''s responsibilities.","vi":"Người quản lý đã triệu tập một cuộc họp để làm rõ trách nhiệm của nhóm."}]', '[{"phrase":"clarify the situation"},{"phrase":"clarify the meaning"},{"phrase":"help clarify"},{"phrase":"further clarify"}]', NULL, '/ˈklærəfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/clari/clarify__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 12, 'commodity', 'hàng hóa; mặt hàng', 'noun', '[{"en":"Oil is one of the most traded commodities in the world.","vi":"Dầu mỏ là một trong những mặt hàng được giao dịch nhiều nhất thế giới."},{"en":"Commodity prices fell sharply during the global recession.","vi":"Giá hàng hóa giảm mạnh trong thời kỳ suy thoái toàn cầu."},{"en":"In many cities, clean water has become a valuable commodity.","vi":"Ở nhiều thành phố, nước sạch đã trở thành một thứ hàng hóa quý giá."}]', '[{"phrase":"commodity prices"},{"phrase":"valuable commodity"},{"phrase":"commodity markets"}]', NULL, '/kəˈmɑːdəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commo/commodity__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 13, 'complement', 'bổ sung; làm hoàn thiện', 'verb', '[{"en":"Online lessons are designed to complement classroom teaching.","vi":"Các bài học trực tuyến được thiết kế để bổ sung cho việc dạy trên lớp."},{"en":"The two studies complement each other well.","vi":"Hai nghiên cứu này bổ sung cho nhau rất tốt."},{"en":"Her technical skills complement his experience in management.","vi":"Kỹ năng chuyên môn của cô ấy bổ sung cho kinh nghiệm quản lý của anh ấy."}]', '[{"phrase":"complement each other"},{"phrase":"perfectly complement"}]', 'complement (bổ sung) ≠ compliment (khen ngợi)', '/ˈkɑːmplɪment/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 14, 'conform', 'tuân theo; phù hợp với', 'verb', '[{"en":"All products must conform to national safety standards.","vi":"Mọi sản phẩm phải tuân theo tiêu chuẩn an toàn quốc gia."},{"en":"Teenagers often feel pressure to conform to their friends'' behavior.","vi":"Thanh thiếu niên thường cảm thấy áp lực phải làm theo hành vi của bạn bè."},{"en":"The results did not conform to our original expectations.","vi":"Kết quả không phù hợp với kỳ vọng ban đầu của chúng tôi."}]', '[{"phrase":"conform to standards"},{"phrase":"conform to rules"},{"phrase":"pressure to conform"}]', 'conform to/with something', '/kənˈfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 15, 'contemporary', 'đương đại; hiện đại; cùng thời', 'adjective', '[{"en":"The museum has a large collection of contemporary art.","vi":"Bảo tàng có một bộ sưu tập lớn về nghệ thuật đương đại."},{"en":"The course examines key issues in contemporary society.","vi":"Khóa học xem xét những vấn đề then chốt trong xã hội hiện đại."},{"en":"Contemporary reports describe the flood as the worst in a century.","vi":"Các bản tường thuật cùng thời mô tả trận lụt là tồi tệ nhất trong một thế kỷ."}]', '[{"phrase":"contemporary art"},{"phrase":"contemporary society"},{"phrase":"contemporary music"}]', NULL, '/kənˈtempəreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontemporary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 16, 'contradict', 'mâu thuẫn với; phủ nhận; cãi lại', 'verb', '[{"en":"These findings contradict the results of earlier studies.","vi":"Những phát hiện này mâu thuẫn với kết quả của các nghiên cứu trước đó."},{"en":"His statement to the police contradicted what he had told reporters.","vi":"Lời khai của anh ta với cảnh sát mâu thuẫn với những gì anh ta đã nói với phóng viên."},{"en":"She felt uncomfortable contradicting her manager in front of clients.","vi":"Cô ấy cảm thấy không thoải mái khi cãi lại quản lý trước mặt khách hàng."}]', '[{"phrase":"contradict the evidence"},{"phrase":"contradict each other"},{"phrase":"directly contradict"}]', NULL, '/ˌkɑːntrəˈdɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontradict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 17, 'crucial', 'cốt yếu; then chốt; quyết định', 'adjective', '[{"en":"Early diagnosis is crucial for successful treatment.","vi":"Chẩn đoán sớm là yếu tố then chốt để điều trị thành công."},{"en":"Teachers play a crucial role in shaping students'' attitudes.","vi":"Giáo viên đóng vai trò quyết định trong việc hình thành thái độ của học sinh."},{"en":"It is crucial that everyone follows the safety procedures.","vi":"Điều cốt yếu là mọi người phải tuân thủ quy trình an toàn."}]', '[{"phrase":"crucial role"},{"phrase":"absolutely crucial"},{"phrase":"crucial for"},{"phrase":"crucial factor"}]', NULL, '/ˈkruːʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cru/cruci/crucial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 18, 'currency', 'tiền tệ; đơn vị tiền tệ', 'noun', '[{"en":"Tourists can exchange foreign currency at the airport.","vi":"Khách du lịch có thể đổi ngoại tệ tại sân bay."},{"en":"The country''s currency lost a third of its value last year.","vi":"Đồng tiền của quốc gia này đã mất một phần ba giá trị vào năm ngoái."},{"en":"Several countries in the region share a single currency.","vi":"Một số quốc gia trong khu vực dùng chung một đơn vị tiền tệ."}]', '[{"phrase":"foreign currency"},{"phrase":"single currency"},{"phrase":"currency exchange"},{"phrase":"local currency"}]', NULL, '/ˈkɜːrənsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/currency__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 19, 'denote', 'biểu thị; chỉ; ký hiệu cho', 'verb', '[{"en":"In the table, an asterisk denotes a significant result.","vi":"Trong bảng, dấu sao biểu thị một kết quả có ý nghĩa thống kê."},{"en":"The letter x is often used to denote an unknown number.","vi":"Chữ x thường được dùng để ký hiệu cho một số chưa biết."},{"en":"Red areas on the map denote regions with heavy rainfall.","vi":"Các vùng màu đỏ trên bản đồ chỉ những khu vực có lượng mưa lớn."}]', '[{"phrase":"used to denote"},{"phrase":"denoted by"}]', NULL, '/dɪˈnəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/denot/denote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 20, 'detect', 'phát hiện; dò ra', 'verb', '[{"en":"The test can detect the disease at a very early stage.","vi":"Xét nghiệm này có thể phát hiện bệnh ở giai đoạn rất sớm."},{"en":"Sensors detected small amounts of gas in the building.","vi":"Cảm biến đã phát hiện một lượng nhỏ khí ga trong tòa nhà."},{"en":"The software is designed to detect errors in financial records.","vi":"Phần mềm được thiết kế để phát hiện lỗi trong hồ sơ tài chính."}]', '[{"phrase":"detect changes"},{"phrase":"detect errors"},{"phrase":"difficult to detect"},{"phrase":"easily detected"}]', NULL, '/dɪˈtekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/detec/detect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 21, 'deviate', 'lệch khỏi; đi chệch', 'verb', '[{"en":"The pilot had to deviate from the planned route because of a storm.","vi":"Phi công phải bay lệch khỏi lộ trình dự kiến vì có bão."},{"en":"Staff should not deviate from the agreed procedures without permission.","vi":"Nhân viên không được làm khác quy trình đã thống nhất khi chưa được phép."},{"en":"The actual costs deviated significantly from the original estimate.","vi":"Chi phí thực tế chênh lệch đáng kể so với ước tính ban đầu."}]', '[{"phrase":"deviate from"},{"phrase":"deviate significantly"},{"phrase":"deviate from the plan"}]', 'deviate from something', '/ˈdiːvieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devia/deviate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 22, 'displace', 'buộc phải rời bỏ nơi ở; thay thế; chiếm chỗ', 'verb', '[{"en":"The floods displaced thousands of families in the region.","vi":"Lũ lụt đã khiến hàng nghìn gia đình trong vùng phải rời bỏ nơi ở."},{"en":"In many offices, email has displaced traditional letters.","vi":"Ở nhiều văn phòng, email đã thay thế thư từ truyền thống."},{"en":"Some workers fear that new technology will displace them.","vi":"Một số công nhân lo sợ rằng công nghệ mới sẽ thay thế họ."}]', '[{"phrase":"displaced people"},{"phrase":"displaced persons"},{"phrase":"be displaced by"}]', NULL, '/dɪsˈpleɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/displ/displace__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 23, 'drama', 'kịch; phim truyền hình; sự kịch tính', 'noun', '[{"en":"She studied drama at university before becoming a teacher.","vi":"Cô ấy học kịch ở trường đại học trước khi trở thành giáo viên."},{"en":"The new television drama follows the lives of hospital staff.","vi":"Bộ phim truyền hình mới kể về cuộc sống của các nhân viên bệnh viện."},{"en":"The rescue was full of drama and lasted several hours.","vi":"Cuộc giải cứu đầy kịch tính và kéo dài nhiều giờ."}]', '[{"phrase":"television drama"},{"phrase":"historical drama"},{"phrase":"drama school"}]', NULL, '/ˈdrɑːmə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/drama__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 24, 'eventual', 'cuối cùng; sau cùng', 'adjective', '[{"en":"Poor management led to the eventual collapse of the company.","vi":"Việc quản lý kém đã dẫn đến sự sụp đổ cuối cùng của công ty."},{"en":"Nobody could have predicted the eventual outcome of the election.","vi":"Không ai có thể đoán trước kết quả cuối cùng của cuộc bầu cử."},{"en":"The eventual winner of the competition was a small local firm.","vi":"Người thắng cuộc sau cùng của cuộc thi là một công ty nhỏ ở địa phương."}]', '[{"phrase":"eventual outcome"},{"phrase":"eventual winner"},{"phrase":"eventual success"}]', 'trạng từ: eventually (cuối cùng)', '/ɪˈventʃuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/event/eventual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 25, 'exhibit', 'trưng bày; thể hiện; biểu hiện', 'verb', '[{"en":"Her paintings will be exhibited at the city gallery next month.","vi":"Các bức tranh của cô ấy sẽ được trưng bày tại phòng tranh thành phố vào tháng tới."},{"en":"Patients exhibited clear signs of improvement after two weeks.","vi":"Bệnh nhân có những dấu hiệu cải thiện rõ rệt sau hai tuần."},{"en":"Some children exhibit behavior problems when they start school.","vi":"Một số trẻ có biểu hiện các vấn đề về hành vi khi bắt đầu đi học."}]', '[{"phrase":"exhibit signs"},{"phrase":"exhibit symptoms"},{"phrase":"exhibit behavior"}]', NULL, '/ɪɡˈzɪbɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhib/exhibit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 26, 'exploit', 'khai thác; tận dụng; bóc lột', 'verb', '[{"en":"The country has not yet fully exploited its natural resources.","vi":"Đất nước này chưa khai thác hết tài nguyên thiên nhiên của mình."},{"en":"Small businesses can exploit new technology to reach more customers.","vi":"Các doanh nghiệp nhỏ có thể tận dụng công nghệ mới để tiếp cận nhiều khách hàng hơn."},{"en":"Some employers exploit workers by paying them very low wages.","vi":"Một số chủ lao động bóc lột công nhân bằng cách trả lương rất thấp."}]', '[{"phrase":"exploit resources"},{"phrase":"fully exploit"},{"phrase":"exploit workers"},{"phrase":"exploit an opportunity"}]', NULL, '/ɪkˈsplɔɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/explo/exploit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 27, 'fluctuate', 'dao động; biến động; lên xuống thất thường', 'verb', '[{"en":"Oil prices fluctuated widely throughout the year.","vi":"Giá dầu biến động mạnh trong suốt cả năm."},{"en":"Temperatures in the desert fluctuate between day and night.","vi":"Nhiệt độ ở sa mạc dao động giữa ban ngày và ban đêm."},{"en":"The number of students tends to fluctuate from one term to the next.","vi":"Số lượng sinh viên thường lên xuống thất thường giữa các học kỳ."}]', '[{"phrase":"fluctuate widely"},{"phrase":"prices fluctuate"},{"phrase":"fluctuate between"}]', NULL, '/ˈflʌktʃueɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flu/fluct/fluctuate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 28, 'guideline', 'hướng dẫn; nguyên tắc chỉ đạo', 'noun', '[{"en":"The government has issued new guidelines on food safety.","vi":"Chính phủ đã ban hành hướng dẫn mới về an toàn thực phẩm."},{"en":"Authors must follow the journal''s guidelines when submitting articles.","vi":"Tác giả phải tuân theo hướng dẫn của tạp chí khi gửi bài."},{"en":"These guidelines apply to all staff working with patient data.","vi":"Các nguyên tắc này áp dụng cho mọi nhân viên làm việc với dữ liệu bệnh nhân."}]', '[{"phrase":"follow guidelines"},{"phrase":"issue guidelines"},{"phrase":"clear guidelines"},{"phrase":"guidelines on"}]', 'thường dùng số nhiều: guidelines', '/ˈɡaɪdlaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guide/guideline__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 29, 'highlight', 'nhấn mạnh; làm nổi bật', 'verb', '[{"en":"The report highlights the need for better public transport.","vi":"Báo cáo nhấn mạnh sự cần thiết của giao thông công cộng tốt hơn."},{"en":"This case highlights the risks of storing data online.","vi":"Trường hợp này làm nổi bật những rủi ro của việc lưu trữ dữ liệu trực tuyến."},{"en":"At the conference, speakers highlighted the importance of early education.","vi":"Tại hội nghị, các diễn giả đã nhấn mạnh tầm quan trọng của giáo dục sớm."}]', '[{"phrase":"highlight the need"},{"phrase":"highlight the importance"},{"phrase":"highlight the problem"}]', NULL, '/ˈhaɪlaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/highl/highlight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-8-01', 30, 'implicit', 'ngầm; ẩn ý; tuyệt đối', 'adjective', '[{"en":"There was an implicit agreement that nobody would discuss the matter.","vi":"Có một thỏa thuận ngầm rằng không ai được bàn về vấn đề này."},{"en":"The criticism was implicit in her comments about the report.","vi":"Lời phê bình ẩn chứa trong nhận xét của cô ấy về bản báo cáo."},{"en":"Patients usually have implicit trust in their doctors.","vi":"Bệnh nhân thường tin tưởng tuyệt đối vào bác sĩ của mình."}]', '[{"phrase":"implicit assumption"},{"phrase":"implicit in"},{"phrase":"implicit trust"}]', 'implicit (ngầm) ≠ explicit (rõ ràng)', '/ɪmˈplɪsɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impli/implicit__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-9-02', 'awl-9', 'Học thuật Sublist 9 · Bộ 2', 'Academic Word List, sublist 9', '#a974ff', 'GraduationCap', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 1, 'mature', 'trưởng thành; chín chắn', 'adjective', '[{"en":"Students in the program tend to be more mature than typical undergraduates.","vi":"Sinh viên trong chương trình này thường chín chắn hơn sinh viên đại học thông thường."},{"en":"These fish take about three years to become fully mature.","vi":"Loài cá này mất khoảng ba năm để trưởng thành hoàn toàn."},{"en":"She handled the difficult situation in a calm and mature way.","vi":"Cô ấy xử lý tình huống khó khăn một cách bình tĩnh và chín chắn."}]', '[{"phrase":"fully mature"},{"phrase":"mature adult"},{"phrase":"mature market"}]', NULL, '/məˈtʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/matur/mature__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 2, 'mediate', 'hòa giải; làm trung gian', 'verb', '[{"en":"A neutral expert was brought in to mediate between the two companies.","vi":"Một chuyên gia trung lập đã được mời đến để làm trung gian giữa hai công ty."},{"en":"The union asked an outside group to mediate the dispute over wages.","vi":"Công đoàn đề nghị một tổ chức bên ngoài hòa giải tranh chấp về tiền lương."},{"en":"Managers are often expected to mediate conflicts within their teams.","vi":"Các nhà quản lý thường được kỳ vọng sẽ hòa giải xung đột trong nhóm của mình."}]', '[{"phrase":"mediate a dispute"},{"phrase":"mediate between"},{"phrase":"mediate conflicts"}]', NULL, '/ˈmiːdieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/media/mediate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 3, 'medium', 'phương tiện (truyền tải); môi trường (nuôi cấy)', 'noun', '[{"en":"Television remains a powerful medium for reaching older audiences.","vi":"Truyền hình vẫn là một phương tiện mạnh mẽ để tiếp cận khán giả lớn tuổi."},{"en":"English is the main medium of instruction at the university.","vi":"Tiếng Anh là ngôn ngữ giảng dạy chính tại trường đại học."},{"en":"The bacteria were grown in a liquid medium for 48 hours.","vi":"Vi khuẩn được nuôi cấy trong môi trường lỏng suốt 48 giờ."}]', '[{"phrase":"medium of instruction"},{"phrase":"medium of communication"},{"phrase":"growth medium"}]', 'Số nhiều: media (phương tiện) hoặc mediums', '/ˈmiːdiəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/mediu/medium__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 4, 'military', '(thuộc) quân sự; quân đội', 'adjective', '[{"en":"The old military base has been turned into a public park.","vi":"Căn cứ quân sự cũ đã được chuyển đổi thành một công viên công cộng."},{"en":"Satellite navigation was first developed for military purposes.","vi":"Hệ thống định vị vệ tinh ban đầu được phát triển cho mục đích quân sự."},{"en":"After finishing school, he spent four years in military service.","vi":"Sau khi học xong, anh ấy đã phục vụ bốn năm trong quân đội."}]', '[{"phrase":"military base"},{"phrase":"military service"},{"phrase":"military purposes"}]', NULL, '/ˈmɪləteri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/milit/military__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 5, 'minimal', 'tối thiểu; rất ít', 'adjective', '[{"en":"The new software requires minimal training for most staff.","vi":"Phần mềm mới chỉ cần đào tạo tối thiểu đối với hầu hết nhân viên."},{"en":"Damage to the building was minimal after the storm.","vi":"Sau cơn bão, tòa nhà chỉ bị thiệt hại rất ít."},{"en":"We aim to complete the project at minimal cost.","vi":"Chúng tôi đặt mục tiêu hoàn thành dự án với chi phí tối thiểu."}]', '[{"phrase":"minimal cost"},{"phrase":"minimal effort"},{"phrase":"minimal impact"}]', NULL, '/ˈmɪnɪml/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minim/minimal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 6, 'mutual', 'lẫn nhau; chung', 'adjective', '[{"en":"Good working relationships are built on mutual respect.","vi":"Các mối quan hệ công việc tốt được xây dựng trên sự tôn trọng lẫn nhau."},{"en":"The agreement is of mutual benefit to both universities.","vi":"Thỏa thuận này mang lại lợi ích chung cho cả hai trường đại học."},{"en":"They were introduced by a mutual friend at a conference.","vi":"Họ được một người bạn chung giới thiệu tại một hội nghị."}]', '[{"phrase":"mutual respect"},{"phrase":"mutual benefit"},{"phrase":"mutual friend"},{"phrase":"mutual understanding"}]', NULL, '/ˈmjuːtʃuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mut/mutua/mutual__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 7, 'norm', 'chuẩn mực; điều bình thường, phổ biến', 'noun', '[{"en":"Working from home has become the norm in many industries.","vi":"Làm việc tại nhà đã trở thành điều bình thường trong nhiều ngành."},{"en":"Social norms influence how people behave in public spaces.","vi":"Các chuẩn mực xã hội ảnh hưởng đến cách mọi người cư xử ở nơi công cộng."},{"en":"In this region, small family farms are still the norm.","vi":"Ở khu vực này, trang trại gia đình nhỏ vẫn là điều phổ biến."}]', '[{"phrase":"social norms"},{"phrase":"become the norm"},{"phrase":"cultural norms"}]', NULL, '/nɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norm_/norm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 8, 'overlap', 'chồng chéo; trùng nhau (một phần)', 'verb', '[{"en":"The two research projects overlap in several important areas.","vi":"Hai dự án nghiên cứu này chồng chéo nhau ở một số lĩnh vực quan trọng."},{"en":"My meeting overlaps with the training session, so I cannot attend both.","vi":"Cuộc họp của tôi trùng giờ với buổi đào tạo nên tôi không thể tham dự cả hai."},{"en":"The responsibilities of the two departments overlapped, which caused confusion.","vi":"Trách nhiệm của hai phòng ban bị chồng chéo, gây ra sự nhầm lẫn."}]', '[{"phrase":"overlap with"},{"phrase":"overlap considerably"},{"phrase":"partially overlap"}]', NULL, '/ˌəʊvərˈlæp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overl/overlap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 9, 'passive', 'thụ động; (ngữ pháp) bị động', 'adjective', '[{"en":"Students learn less when they remain passive during lectures.","vi":"Sinh viên học được ít hơn khi họ thụ động trong các giờ giảng."},{"en":"Scientific reports often use the passive voice.","vi":"Các báo cáo khoa học thường dùng thể bị động."},{"en":"Instead of taking a passive role, she questioned every decision.","vi":"Thay vì đóng vai trò thụ động, cô ấy đặt câu hỏi về mọi quyết định."}]', '[{"phrase":"passive voice"},{"phrase":"passive role"},{"phrase":"passive learning"}]', NULL, '/ˈpæsɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passi/passive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 10, 'portion', 'phần; khẩu phần', 'noun', '[{"en":"A large portion of the budget is spent on salaries.","vi":"Một phần lớn ngân sách được chi cho tiền lương."},{"en":"Only a small portion of the population owns a car.","vi":"Chỉ một phần nhỏ dân số sở hữu ô tô."},{"en":"Restaurants have been criticized for serving very large portions.","vi":"Các nhà hàng bị chỉ trích vì phục vụ những khẩu phần quá lớn."}]', '[{"phrase":"a large portion of"},{"phrase":"a small portion of"},{"phrase":"portion size"}]', NULL, '/ˈpɔːrʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/porti/portion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 11, 'preliminary', 'sơ bộ; ban đầu', 'adjective', '[{"en":"Preliminary results suggest that the new drug is safe.","vi":"Kết quả sơ bộ cho thấy loại thuốc mới là an toàn."},{"en":"The committee held a preliminary meeting to discuss the plan.","vi":"Ủy ban đã tổ chức một cuộc họp sơ bộ để thảo luận kế hoạch."},{"en":"These findings are only preliminary and need further testing.","vi":"Những phát hiện này chỉ mang tính sơ bộ và cần được kiểm chứng thêm."}]', '[{"phrase":"preliminary results"},{"phrase":"preliminary findings"},{"phrase":"preliminary study"}]', NULL, '/prɪˈlɪmɪneri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preli/preliminary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 12, 'protocol', 'quy trình; giao thức', 'noun', '[{"en":"All staff must follow the safety protocol when handling chemicals.","vi":"Mọi nhân viên phải tuân theo quy trình an toàn khi xử lý hóa chất."},{"en":"The study protocol was approved by the ethics committee.","vi":"Quy trình nghiên cứu đã được hội đồng đạo đức phê duyệt."},{"en":"Computers use a common protocol to exchange data over the internet.","vi":"Các máy tính sử dụng một giao thức chung để trao đổi dữ liệu qua internet."}]', '[{"phrase":"follow protocol"},{"phrase":"safety protocol"},{"phrase":"study protocol"}]', NULL, '/ˈprəʊtəkɑːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proto/protocol__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 13, 'qualitative', 'định tính', 'adjective', '[{"en":"The researchers used qualitative methods such as interviews and group discussions.","vi":"Các nhà nghiên cứu sử dụng phương pháp định tính như phỏng vấn và thảo luận nhóm."},{"en":"Qualitative data can explain why customers made certain choices.","vi":"Dữ liệu định tính có thể giải thích vì sao khách hàng đưa ra những lựa chọn nhất định."},{"en":"Her thesis combines qualitative and quantitative research.","vi":"Luận văn của cô ấy kết hợp nghiên cứu định tính và định lượng."}]', '[{"phrase":"qualitative research"},{"phrase":"qualitative data"},{"phrase":"qualitative analysis"}]', 'qualitative (định tính) ≠ quantitative (định lượng)', '/ˈkwɑːlɪteɪtɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/qualitative__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 14, 'refine', 'tinh chỉnh; cải tiến; tinh chế', 'verb', '[{"en":"We further refined the survey questions after the first trial.","vi":"Chúng tôi đã tinh chỉnh thêm các câu hỏi khảo sát sau lần thử nghiệm đầu tiên."},{"en":"The company continues to refine its manufacturing process.","vi":"Công ty tiếp tục cải tiến quy trình sản xuất của mình."},{"en":"Crude oil must be refined before it can be used as fuel.","vi":"Dầu thô phải được tinh chế trước khi có thể dùng làm nhiên liệu."}]', '[{"phrase":"further refine"},{"phrase":"refine a process"},{"phrase":"refine a technique"}]', NULL, '/rɪˈfaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refin/refine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 15, 'relax', 'nới lỏng (quy định); thư giãn', 'verb', '[{"en":"The city relaxed the rules on parking during the holiday season.","vi":"Thành phố đã nới lỏng quy định về đỗ xe trong mùa lễ."},{"en":"Many employees find it hard to relax after work.","vi":"Nhiều nhân viên cảm thấy khó thư giãn sau giờ làm việc."},{"en":"Banks relaxed lending standards before the financial crisis.","vi":"Các ngân hàng đã nới lỏng tiêu chuẩn cho vay trước cuộc khủng hoảng tài chính."}]', '[{"phrase":"relax the rules"},{"phrase":"relax restrictions"},{"phrase":"relax standards"}]', NULL, '/rɪˈlæks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relax/relax__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 16, 'restrain', 'kiềm chế; hạn chế', 'verb', '[{"en":"The central bank raised interest rates to restrain inflation.","vi":"Ngân hàng trung ương đã tăng lãi suất để kiềm chế lạm phát."},{"en":"She had to restrain herself from interrupting the speaker.","vi":"Cô ấy phải kiềm chế bản thân để không ngắt lời người phát biểu."},{"en":"New rules aim to restrain the growth of public spending.","vi":"Các quy định mới nhằm hạn chế sự gia tăng chi tiêu công."}]', '[{"phrase":"restrain inflation"},{"phrase":"restrain yourself"},{"phrase":"restrain spending"}]', 'restrain sb from doing sth', '/rɪˈstreɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restrain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 17, 'revolution', 'cuộc cách mạng; vòng quay', 'noun', '[{"en":"The Industrial Revolution changed the way goods were produced.","vi":"Cuộc Cách mạng Công nghiệp đã thay đổi cách thức sản xuất hàng hóa."},{"en":"Smartphones started a revolution in how people access information.","vi":"Điện thoại thông minh đã khởi đầu một cuộc cách mạng trong cách con người tiếp cận thông tin."},{"en":"The wheel makes one complete revolution every two seconds.","vi":"Bánh xe quay trọn một vòng sau mỗi hai giây."}]', '[{"phrase":"industrial revolution"},{"phrase":"digital revolution"},{"phrase":"technological revolution"}]', NULL, '/ˌrevəˈluːʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revol/revolution__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 18, 'rigid', 'cứng nhắc; cứng', 'adjective', '[{"en":"The company''s rigid rules left little room for new ideas.","vi":"Những quy định cứng nhắc của công ty hầu như không chừa chỗ cho ý tưởng mới."},{"en":"Critics say the school system is too rigid for creative students.","vi":"Những người phê bình cho rằng hệ thống trường học quá cứng nhắc đối với học sinh sáng tạo."},{"en":"The box is made of rigid plastic to protect the equipment.","vi":"Chiếc hộp được làm bằng nhựa cứng để bảo vệ thiết bị."}]', '[{"phrase":"rigid rules"},{"phrase":"rigid structure"},{"phrase":"rigid plastic"}]', NULL, '/ˈrɪdʒɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rig/rigid/rigid__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 19, 'route', 'tuyến đường; con đường (để đạt được điều gì)', 'noun', '[{"en":"The new bus route connects the airport with the city center.","vi":"Tuyến xe buýt mới nối sân bay với trung tâm thành phố."},{"en":"Shipping companies are looking for cheaper routes to Europe.","vi":"Các công ty vận tải biển đang tìm các tuyến đường rẻ hơn đến châu Âu."},{"en":"For many young people, education is the main route to a better job.","vi":"Với nhiều người trẻ, giáo dục là con đường chính để có công việc tốt hơn."}]', '[{"phrase":"bus route"},{"phrase":"trade route"},{"phrase":"route to"}]', NULL, '/ruːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/route/route__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 20, 'scenario', 'kịch bản; tình huống (giả định)', 'noun', '[{"en":"In the worst-case scenario, the project could be delayed by a year.","vi":"Trong kịch bản xấu nhất, dự án có thể bị chậm một năm."},{"en":"Economists modeled several scenarios for future energy prices.","vi":"Các nhà kinh tế đã xây dựng mô hình cho một số kịch bản về giá năng lượng trong tương lai."},{"en":"Trainees practice responding to emergency scenarios in a safe setting.","vi":"Học viên thực hành xử lý các tình huống khẩn cấp trong một môi trường an toàn."}]', '[{"phrase":"worst-case scenario"},{"phrase":"likely scenario"},{"phrase":"possible scenario"}]', NULL, '/səˈnæriəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sce/scena/scenario__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 21, 'sphere', 'lĩnh vực; phạm vi; hình cầu', 'noun', '[{"en":"Cooperation between the two countries now extends to the sphere of education.","vi":"Sự hợp tác giữa hai nước nay đã mở rộng sang lĩnh vực giáo dục."},{"en":"Each manager has a clear sphere of responsibility within the firm.","vi":"Mỗi quản lý có một phạm vi trách nhiệm rõ ràng trong công ty."},{"en":"The Earth is not a perfect sphere but is slightly flattened at the poles.","vi":"Trái Đất không phải là một hình cầu hoàn hảo mà hơi dẹt ở hai cực."}]', '[{"phrase":"public sphere"},{"phrase":"sphere of influence"},{"phrase":"perfect sphere"}]', NULL, '/sfɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sph/spher/sphere__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 22, 'subordinate', 'cấp dưới; thuộc cấp', 'noun', '[{"en":"A good manager listens carefully to the concerns of subordinates.","vi":"Một nhà quản lý giỏi lắng nghe kỹ những lo ngại của cấp dưới."},{"en":"She was criticized for blaming her subordinates for the mistake.","vi":"Cô ấy bị chỉ trích vì đổ lỗi cho cấp dưới về sai sót đó."},{"en":"The survey asked employees how they communicate with superiors and subordinates.","vi":"Cuộc khảo sát hỏi nhân viên về cách họ giao tiếp với cấp trên và cấp dưới."}]', '[{"phrase":"superiors and subordinates"},{"phrase":"immediate subordinate"}]', 'Cũng là tính từ: thứ yếu, phụ thuộc (subordinate to)', '/səˈbɔːrdɪnət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subor/subordinate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 23, 'supplement', 'phần bổ sung; thực phẩm bổ sung', 'noun', '[{"en":"Doctors may recommend a vitamin D supplement during the winter.","vi":"Bác sĩ có thể khuyên dùng thực phẩm bổ sung vitamin D vào mùa đông."},{"en":"The online course is a supplement to classroom teaching, not a replacement.","vi":"Khóa học trực tuyến là phần bổ sung cho việc giảng dạy trên lớp, chứ không thay thế nó."},{"en":"Many older adults take dietary supplements without asking a doctor.","vi":"Nhiều người lớn tuổi dùng thực phẩm bổ sung mà không hỏi ý kiến bác sĩ."}]', '[{"phrase":"dietary supplement"},{"phrase":"vitamin supplement"},{"phrase":"supplement to"}]', NULL, '/ˈsʌplɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supplement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 24, 'suspend', 'tạm ngừng; đình chỉ', 'verb', '[{"en":"The factory suspended production for a week after the fire.","vi":"Nhà máy đã tạm ngừng sản xuất một tuần sau vụ hỏa hoạn."},{"en":"Two players were suspended for breaking team rules.","vi":"Hai cầu thủ bị đình chỉ vì vi phạm nội quy của đội."},{"en":"The airline has suspended all flights to the region until further notice.","vi":"Hãng hàng không đã tạm ngừng mọi chuyến bay đến khu vực này cho đến khi có thông báo mới."}]', '[{"phrase":"suspend production"},{"phrase":"suspend flights"},{"phrase":"temporarily suspend"}]', NULL, '/səˈspend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/suspe/suspend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 25, 'team', 'nhóm; đội', 'noun', '[{"en":"Our research team includes experts from five different countries.","vi":"Nhóm nghiên cứu của chúng tôi gồm các chuyên gia đến từ năm quốc gia khác nhau."},{"en":"She was asked to lead a small team of software engineers.","vi":"Cô ấy được giao dẫn dắt một nhóm nhỏ các kỹ sư phần mềm."},{"en":"The national team trained hard for the tournament.","vi":"Đội tuyển quốc gia đã tập luyện chăm chỉ cho giải đấu."}]', '[{"phrase":"research team"},{"phrase":"lead a team"},{"phrase":"team member"},{"phrase":"national team"}]', NULL, '/tiːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/team_/team__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 26, 'temporary', 'tạm thời', 'adjective', '[{"en":"The company hired temporary staff during the busy season.","vi":"Công ty đã thuê nhân viên tạm thời trong mùa cao điểm."},{"en":"Classes will be held in a temporary building until repairs are finished.","vi":"Các lớp học sẽ được tổ chức trong một tòa nhà tạm cho đến khi sửa chữa xong."},{"en":"Experts believe the drop in prices is only temporary.","vi":"Các chuyên gia cho rằng việc giá giảm chỉ là tạm thời."}]', '[{"phrase":"temporary staff"},{"phrase":"temporary job"},{"phrase":"temporary solution"}]', NULL, '/ˈtempəreri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tem/tempo/temporary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 27, 'trigger', 'gây ra; kích hoạt', 'verb', '[{"en":"The announcement triggered a sharp fall in share prices.","vi":"Thông báo đó đã gây ra sự sụt giảm mạnh của giá cổ phiếu."},{"en":"Certain foods can trigger allergic reactions in children.","vi":"Một số loại thực phẩm có thể gây ra phản ứng dị ứng ở trẻ em."},{"en":"Opening the door without a code will trigger an alarm.","vi":"Mở cửa mà không nhập mã sẽ kích hoạt chuông báo động."}]', '[{"phrase":"trigger a reaction"},{"phrase":"trigger an alarm"},{"phrase":"trigger a debate"}]', NULL, '/ˈtrɪɡər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trigg/trigger__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 28, 'unify', 'thống nhất; hợp nhất', 'verb', '[{"en":"The new system unifies customer records from all branches.","vi":"Hệ thống mới hợp nhất hồ sơ khách hàng từ tất cả các chi nhánh."},{"en":"The coach''s main task was to unify a divided team.","vi":"Nhiệm vụ chính của huấn luyện viên là thống nhất lại một đội đang chia rẽ."},{"en":"Scientists have long attempted to unify these two theories.","vi":"Các nhà khoa học từ lâu đã cố gắng thống nhất hai lý thuyết này."}]', '[{"phrase":"attempt to unify"},{"phrase":"unify the country"},{"phrase":"help unify"}]', NULL, '/ˈjuːnɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unify/unify__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 29, 'violate', 'vi phạm', 'verb', '[{"en":"The company was fined for violating environmental laws.","vi":"Công ty bị phạt vì vi phạm luật môi trường."},{"en":"Sharing patient records without consent violates privacy rules.","vi":"Chia sẻ hồ sơ bệnh nhân khi chưa được đồng ý là vi phạm quy định về quyền riêng tư."},{"en":"Researchers must not violate the terms of their agreement.","vi":"Các nhà nghiên cứu không được vi phạm các điều khoản trong thỏa thuận của họ."}]', '[{"phrase":"violate the law"},{"phrase":"violate the terms"},{"phrase":"violate rules"}]', NULL, '/ˈvaɪəleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vio/viola/violate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-9-02', 30, 'vision', 'tầm nhìn; thị lực', 'noun', '[{"en":"The new director has a clear vision for the university''s future.","vi":"Giám đốc mới có tầm nhìn rõ ràng cho tương lai của trường đại học."},{"en":"Regular eye tests can detect problems with vision early.","vi":"Khám mắt định kỳ có thể phát hiện sớm các vấn đề về thị lực."},{"en":"The company''s vision is to make clean energy affordable for everyone.","vi":"Tầm nhìn của công ty là giúp mọi người đều có thể chi trả cho năng lượng sạch."}]', '[{"phrase":"clear vision"},{"phrase":"vision for the future"},{"phrase":"poor vision"}]', NULL, '/ˈvɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visio/vision__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('awl-10-01', 'awl-10', 'Học thuật Sublist 10 · Bộ 1', 'Academic Word List, sublist 10', '#a974ff', 'GraduationCap', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 1, 'adjacent', 'liền kề; kế bên', 'adjective', '[{"en":"The new laboratory will be built on land adjacent to the hospital.","vi":"Phòng thí nghiệm mới sẽ được xây trên khu đất liền kề bệnh viện."},{"en":"Cells in adjacent areas of the tissue showed similar damage.","vi":"Các tế bào ở những vùng liền kề của mô cho thấy tổn thương tương tự."},{"en":"Two adjacent countries signed an agreement to share water resources.","vi":"Hai quốc gia kế bên nhau đã ký thỏa thuận chia sẻ nguồn nước."}]', '[{"phrase":"adjacent to"},{"phrase":"adjacent areas"},{"phrase":"adjacent land"}]', 'adjacent to + danh từ', '/əˈdʒeɪsnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjac/adjacent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 2, 'albeit', 'mặc dù; dù là', 'conjunction', '[{"en":"The economy is growing, albeit slowly, according to the latest figures.","vi":"Theo số liệu mới nhất, nền kinh tế đang tăng trưởng, dù là chậm."},{"en":"The treatment was effective, albeit only for a small number of patients.","vi":"Phương pháp điều trị có hiệu quả, mặc dù chỉ với một số ít bệnh nhân."},{"en":"Prices rose again last month, albeit at a lower rate.","vi":"Giá cả lại tăng trong tháng trước, dù là với tốc độ thấp hơn."}]', '[{"phrase":"albeit slowly"},{"phrase":"albeit briefly"},{"phrase":"albeit at a lower rate"}]', 'Trang trọng; thường theo sau là tính từ, trạng từ hoặc cụm giới từ', '/ˌɔːlˈbiːɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alb/albei/albeit__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 3, 'assemble', 'lắp ráp; tập hợp', 'verb', '[{"en":"The cars are assembled in a factory outside the capital.","vi":"Những chiếc ô tô được lắp ráp tại một nhà máy ở ngoại ô thủ đô."},{"en":"Workers can assemble the device in less than ten minutes.","vi":"Công nhân có thể lắp ráp thiết bị này trong chưa đầy mười phút."},{"en":"The university assembled a team of experts to study the problem.","vi":"Trường đại học đã tập hợp một nhóm chuyên gia để nghiên cứu vấn đề này."}]', '[{"phrase":"assemble a team"},{"phrase":"assemble evidence"},{"phrase":"assemble parts"}]', NULL, '/əˈsembl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assem/assemble__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 4, 'collapse', 'sụp đổ; đổ sập; ngã quỵ', 'verb', '[{"en":"Several old buildings collapsed during the earthquake last night.","vi":"Nhiều tòa nhà cũ đã đổ sập trong trận động đất tối qua."},{"en":"The company collapsed completely after years of poor management.","vi":"Công ty đã sụp đổ hoàn toàn sau nhiều năm quản lý yếu kém."},{"en":"One runner collapsed near the finish line and was taken to the hospital.","vi":"Một vận động viên đã ngã quỵ gần vạch đích và được đưa đến bệnh viện."}]', '[{"phrase":"collapse completely"},{"phrase":"nearly collapse"},{"phrase":"the roof collapsed"}]', NULL, '/kəˈlæps/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colla/collapse__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 5, 'colleague', 'đồng nghiệp', 'noun', '[{"en":"She discussed the proposal with her colleagues before the meeting.","vi":"Cô ấy đã thảo luận đề xuất với các đồng nghiệp trước cuộc họp."},{"en":"My colleague and I published a paper on climate change last year.","vi":"Tôi và đồng nghiệp đã công bố một bài báo về biến đổi khí hậu năm ngoái."},{"en":"A former colleague recommended him for the position.","vi":"Một đồng nghiệp cũ đã giới thiệu anh ấy vào vị trí này."}]', '[{"phrase":"former colleague"},{"phrase":"close colleague"},{"phrase":"senior colleague"}]', NULL, '/ˈkɑːliːɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/colleague__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 6, 'compile', 'biên soạn; tổng hợp', 'verb', '[{"en":"The report was compiled from interviews with over two hundred teachers.","vi":"Báo cáo được biên soạn từ các cuộc phỏng vấn với hơn hai trăm giáo viên."},{"en":"We need to compile a list of suppliers for the new project.","vi":"Chúng ta cần lập một danh sách nhà cung cấp cho dự án mới."},{"en":"These figures were compiled by the national statistics office.","vi":"Những số liệu này do cơ quan thống kê quốc gia tổng hợp."}]', '[{"phrase":"compile a list"},{"phrase":"compile a report"},{"phrase":"compile data"},{"phrase":"compile statistics"}]', NULL, '/kəmˈpaɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compi/compile__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 7, 'conceive', 'nghĩ ra; hình dung', 'verb', '[{"en":"The project was originally conceived as a small local study.","vi":"Dự án ban đầu được nghĩ ra như một nghiên cứu nhỏ ở địa phương."},{"en":"It is hard to conceive of a world without the internet.","vi":"Thật khó để hình dung một thế giới không có internet."},{"en":"Engineers conceived a cheaper way to store solar energy.","vi":"Các kỹ sư đã nghĩ ra một cách rẻ hơn để lưu trữ năng lượng mặt trời."}]', '[{"phrase":"conceive of"},{"phrase":"originally conceived"},{"phrase":"conceive an idea"},{"phrase":"conceive a plan"}]', 'conceive of sth: hình dung điều gì', '/kənˈsiːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconceive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 8, 'convince', 'thuyết phục; làm cho tin', 'verb', '[{"en":"The results convinced the committee to continue funding the research.","vi":"Kết quả đã thuyết phục hội đồng tiếp tục tài trợ cho nghiên cứu."},{"en":"I am not fully convinced that this method will work.","vi":"Tôi không hoàn toàn tin rằng phương pháp này sẽ hiệu quả."},{"en":"She tried to convince investors that the plan was realistic.","vi":"Cô ấy đã cố thuyết phục các nhà đầu tư rằng kế hoạch này khả thi."}]', '[{"phrase":"fully convinced"},{"phrase":"convince somebody to"},{"phrase":"convince somebody that"}]', 'convince sb to do sth / convince sb that ...', '/kənˈvɪns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvince__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 9, 'depress', 'làm giảm (giá, nhu cầu); làm chán nản', 'verb', '[{"en":"Higher interest rates could depress demand for new homes.","vi":"Lãi suất cao hơn có thể làm giảm nhu cầu mua nhà mới."},{"en":"Cheap imports have depressed prices for local farmers.","vi":"Hàng nhập khẩu giá rẻ đã làm giảm giá bán của nông dân trong nước."},{"en":"Months without work had begun to depress him.","vi":"Nhiều tháng không có việc làm đã bắt đầu khiến anh ấy chán nản."}]', '[{"phrase":"depress prices"},{"phrase":"depress demand"},{"phrase":"depress wages"}]', NULL, '/dɪˈpres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depre/depress__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 10, 'encounter', 'gặp phải; bắt gặp', 'verb', '[{"en":"The team encountered several problems during the first stage of testing.","vi":"Nhóm đã gặp phải một số vấn đề trong giai đoạn thử nghiệm đầu tiên."},{"en":"Students often encounter difficulties when writing their first research paper.","vi":"Sinh viên thường gặp khó khăn khi viết bài nghiên cứu đầu tiên."},{"en":"This species is rarely encountered outside the tropical forest.","vi":"Loài này hiếm khi được bắt gặp bên ngoài rừng nhiệt đới."}]', '[{"phrase":"encounter problems"},{"phrase":"encounter difficulties"},{"phrase":"encounter resistance"}]', NULL, '/ɪnˈkaʊntər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enc/encou/encounter__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 11, 'enormous', 'to lớn; khổng lồ', 'adjective', '[{"en":"The new policy has had an enormous impact on small businesses.","vi":"Chính sách mới đã có tác động to lớn đến các doanh nghiệp nhỏ."},{"en":"Building the bridge required an enormous amount of money.","vi":"Việc xây cây cầu đòi hỏi một khoản tiền khổng lồ."},{"en":"There are enormous differences in income between rural and urban areas.","vi":"Có sự chênh lệch rất lớn về thu nhập giữa nông thôn và thành thị."}]', '[{"phrase":"enormous amount"},{"phrase":"enormous impact"},{"phrase":"enormous pressure"}]', NULL, '/ɪˈnɔːrməs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eno/enorm/enormous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 12, 'forthcoming', 'sắp tới; sẵn có (được cung cấp)', 'adjective', '[{"en":"Full details will be published in the forthcoming report.","vi":"Thông tin chi tiết sẽ được công bố trong báo cáo sắp tới."},{"en":"The results will be discussed at the forthcoming conference in May.","vi":"Kết quả sẽ được thảo luận tại hội nghị sắp tới vào tháng Năm."},{"en":"Despite repeated requests, no further information was forthcoming from the ministry.","vi":"Dù đã yêu cầu nhiều lần, bộ vẫn không cung cấp thêm thông tin nào."}]', '[{"phrase":"forthcoming report"},{"phrase":"forthcoming conference"},{"phrase":"forthcoming book"}]', 'be forthcoming: được cung cấp, sẵn có', '/ˌfɔːrθˈkʌmɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forth/forthcoming__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 13, 'incline', 'có xu hướng; nghiêng về', 'verb', '[{"en":"Many managers are inclined to hire people they already know.","vi":"Nhiều nhà quản lý có xu hướng tuyển những người họ đã quen biết."},{"en":"I''m inclined to agree with the reviewers on this point.","vi":"Tôi nghiêng về việc đồng ý với các nhà phản biện ở điểm này."},{"en":"Rising costs may incline some firms to move production overseas.","vi":"Chi phí tăng có thể khiến một số công ty có xu hướng chuyển sản xuất ra nước ngoài."}]', '[{"phrase":"inclined to agree"},{"phrase":"inclined to believe"},{"phrase":"be inclined to"}]', 'Thường dùng bị động: be inclined to do sth', '/ɪnˈklaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incli/incline__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 14, 'integrity', 'sự chính trực; tính toàn vẹn', 'noun', '[{"en":"Copying another student''s work is a serious breach of academic integrity.","vi":"Sao chép bài của sinh viên khác là vi phạm nghiêm trọng liêm chính học thuật."},{"en":"The auditor was widely respected for her honesty and integrity.","vi":"Kiểm toán viên ấy được nhiều người kính trọng vì sự trung thực và chính trực."},{"en":"Engineers checked the structural integrity of the bridge after the flood.","vi":"Các kỹ sư đã kiểm tra độ toàn vẹn kết cấu của cây cầu sau trận lũ."}]', '[{"phrase":"academic integrity"},{"phrase":"structural integrity"},{"phrase":"data integrity"},{"phrase":"personal integrity"}]', 'Không đếm được', '/ɪnˈteɡrəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integrity__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 15, 'intrinsic', 'nội tại; vốn có', 'adjective', '[{"en":"The old painting has little intrinsic value, but the family treasures it.","vi":"Bức tranh cũ có ít giá trị nội tại, nhưng gia đình rất trân quý nó."},{"en":"Students with strong intrinsic motivation tend to learn more effectively.","vi":"Những sinh viên có động lực nội tại mạnh thường học hiệu quả hơn."},{"en":"Risk is intrinsic to starting any new business.","vi":"Rủi ro là điều vốn có khi bắt đầu bất kỳ công việc kinh doanh mới nào."}]', '[{"phrase":"intrinsic value"},{"phrase":"intrinsic motivation"},{"phrase":"intrinsic to"}]', 'intrinsic to sth: vốn có ở điều gì', '/ɪnˈtrɪnzɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intri/intrinsic__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 16, 'invoke', 'viện dẫn; áp dụng (luật, điều khoản)', 'verb', '[{"en":"The company invoked a clause in the contract to cancel the deal.","vi":"Công ty đã áp dụng một điều khoản trong hợp đồng để hủy thỏa thuận."},{"en":"The author invokes several earlier studies to support her argument.","vi":"Tác giả viện dẫn một số nghiên cứu trước đây để củng cố lập luận của mình."},{"en":"Judges sometimes invoke the principle of fairness in difficult cases.","vi":"Các thẩm phán đôi khi viện dẫn nguyên tắc công bằng trong những vụ việc khó."}]', '[{"phrase":"invoke a clause"},{"phrase":"invoke the principle"},{"phrase":"invoke a right"}]', NULL, '/ɪnˈvəʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invok/invoke__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 17, 'levy', 'đánh (thuế); thu (phí, tiền phạt)', 'verb', '[{"en":"The city plans to levy a small tax on hotel rooms.","vi":"Thành phố dự định đánh một khoản thuế nhỏ lên phòng khách sạn."},{"en":"A heavy fine was levied on the company for polluting the river.","vi":"Công ty bị phạt một khoản tiền lớn vì gây ô nhiễm dòng sông."},{"en":"Many countries levy higher taxes on tobacco and alcohol.","vi":"Nhiều quốc gia đánh thuế cao hơn đối với thuốc lá và rượu bia."}]', '[{"phrase":"levy a tax"},{"phrase":"levy a fine"},{"phrase":"levy taxes on"}]', 'levy sth on sb/sth; cũng là danh từ: khoản thuế', '/ˈlevi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lev/levy_/levy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 18, 'likewise', 'tương tự; cũng vậy', 'adverb', '[{"en":"Rents rose sharply in the capital and likewise increased in smaller cities.","vi":"Giá thuê nhà tăng mạnh ở thủ đô và tương tự cũng tăng ở các thành phố nhỏ hơn."},{"en":"The first group followed the new rules, and the others did likewise.","vi":"Nhóm đầu tiên tuân theo quy định mới, và các nhóm khác cũng làm như vậy."},{"en":"Teachers should respect their students, and likewise students should respect teachers.","vi":"Giáo viên nên tôn trọng học sinh, và tương tự, học sinh cũng nên tôn trọng giáo viên."}]', '[{"phrase":"do likewise"},{"phrase":"and likewise"}]', NULL, '/ˈlaɪkwaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lik/likew/likewise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 19, 'nonetheless', 'tuy nhiên; dù vậy', 'adverb', '[{"en":"The sample was small, but the results are nonetheless important.","vi":"Mẫu nghiên cứu nhỏ, nhưng dù vậy kết quả vẫn quan trọng."},{"en":"The task was difficult; nonetheless, they completed it on time.","vi":"Nhiệm vụ rất khó; tuy nhiên, họ vẫn hoàn thành đúng hạn."},{"en":"The plan is risky but nonetheless worth trying.","vi":"Kế hoạch này rủi ro nhưng dù vậy vẫn đáng để thử."}]', '[{"phrase":"but nonetheless"},{"phrase":"nonetheless important"}]', NULL, '/ˌnʌnðəˈles/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/non/nonet/nonetheless__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 20, 'notwithstanding', 'mặc dù; bất chấp', 'preposition', '[{"en":"Notwithstanding the difficulties, the team finished the project on time.","vi":"Mặc dù gặp nhiều khó khăn, nhóm vẫn hoàn thành dự án đúng hạn."},{"en":"The new rules apply to all staff, notwithstanding any earlier agreement.","vi":"Quy định mới áp dụng cho toàn bộ nhân viên, bất chấp mọi thỏa thuận trước đó."},{"en":"Economic problems notwithstanding, the region continues to attract foreign investors.","vi":"Bất chấp những khó khăn kinh tế, khu vực này vẫn tiếp tục thu hút nhà đầu tư nước ngoài."}]', '[{"phrase":"notwithstanding the difficulties"},{"phrase":"notwithstanding the fact that"}]', 'Rất trang trọng; có thể đứng sau danh từ', '/ˌnɑːtwɪθˈstændɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notwi/notwithstanding__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 21, 'odd', 'kỳ lạ; (số) lẻ', 'adjective', '[{"en":"It seems odd that nobody noticed the error earlier.","vi":"Thật lạ là không ai phát hiện ra lỗi này sớm hơn."},{"en":"Each participant with an odd number joined the first group.","vi":"Mỗi người tham gia mang số lẻ được xếp vào nhóm thứ nhất."},{"en":"There was something odd about the results of the second test.","vi":"Có điều gì đó kỳ lạ trong kết quả của lần kiểm tra thứ hai."}]', '[{"phrase":"odd number"},{"phrase":"seem odd"},{"phrase":"something odd"}]', 'odd number (số lẻ) ≠ even number (số chẵn)', '/ɑːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/odd/odd__/odd__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 22, 'ongoing', 'đang diễn ra; liên tục', 'adjective', '[{"en":"The investigation into the accident is still ongoing.","vi":"Cuộc điều tra về vụ tai nạn vẫn đang diễn ra."},{"en":"Ongoing research suggests the drug may help older patients.","vi":"Nghiên cứu đang được tiến hành cho thấy loại thuốc này có thể giúp ích cho bệnh nhân lớn tuổi."},{"en":"New staff receive ongoing training throughout their first year.","vi":"Nhân viên mới được đào tạo liên tục trong suốt năm đầu tiên."}]', '[{"phrase":"ongoing research"},{"phrase":"ongoing training"},{"phrase":"ongoing support"},{"phrase":"ongoing process"}]', NULL, '/ˈɑːnɡəʊɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ong/ongoi/ongoing__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 23, 'panel', 'ban, hội đồng (chuyên gia); tấm', 'noun', '[{"en":"A panel of experts will review all the applications.","vi":"Một hội đồng chuyên gia sẽ xem xét tất cả các hồ sơ."},{"en":"The panel discussion focused on the future of online education.","vi":"Buổi thảo luận chuyên đề tập trung vào tương lai của giáo dục trực tuyến."},{"en":"The school uses solar panels to produce most of its electricity.","vi":"Ngôi trường sử dụng tấm pin mặt trời để tạo ra phần lớn lượng điện."}]', '[{"phrase":"panel of experts"},{"phrase":"panel discussion"},{"phrase":"solar panel"},{"phrase":"expert panel"}]', NULL, '/ˈpænl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pan/panel/panel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 24, 'persist', 'vẫn tiếp diễn; kéo dài; kiên trì', 'verb', '[{"en":"If the symptoms persist, patients should see a doctor.","vi":"Nếu các triệu chứng kéo dài, bệnh nhân nên đi khám bác sĩ."},{"en":"Inequality between regions has persisted for several decades.","vi":"Sự bất bình đẳng giữa các vùng đã tiếp diễn trong nhiều thập kỷ."},{"en":"She persisted with her research despite a lack of funding.","vi":"Cô ấy vẫn kiên trì với nghiên cứu của mình dù thiếu kinh phí."}]', '[{"phrase":"symptoms persist"},{"phrase":"persist with"},{"phrase":"persist in"},{"phrase":"problems persist"}]', 'persist in/with sth', '/pərˈsɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persi/persist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 25, 'pose', 'gây ra (mối đe dọa, rủi ro); đặt ra (câu hỏi)', 'verb', '[{"en":"Rising sea levels pose a serious threat to coastal cities.","vi":"Mực nước biển dâng cao gây ra mối đe dọa nghiêm trọng cho các thành phố ven biển."},{"en":"Poor storage conditions may pose a risk to public health.","vi":"Điều kiện bảo quản kém có thể gây rủi ro cho sức khỏe cộng đồng."},{"en":"The report poses important questions about data privacy.","vi":"Báo cáo đặt ra những câu hỏi quan trọng về quyền riêng tư dữ liệu."}]', '[{"phrase":"pose a threat"},{"phrase":"pose a risk"},{"phrase":"pose a challenge"},{"phrase":"pose a question"}]', NULL, '/pəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/pose_/pose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 26, 'reluctance', 'sự miễn cưỡng; sự ngần ngại', 'noun', '[{"en":"Many firms show reluctance to invest during uncertain times.","vi":"Nhiều công ty tỏ ra ngần ngại đầu tư trong thời kỳ bất ổn."},{"en":"Her reluctance to share the data slowed down the project.","vi":"Sự miễn cưỡng chia sẻ dữ liệu của cô ấy đã làm chậm dự án."},{"en":"Despite his initial reluctance, he agreed to lead the team.","vi":"Dù ban đầu còn ngần ngại, anh ấy đã đồng ý dẫn dắt nhóm."}]', '[{"phrase":"reluctance to"},{"phrase":"initial reluctance"},{"phrase":"show reluctance"}]', 'reluctance to do sth', '/rɪˈlʌktəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/reluc/reluctance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 27, 'so-called', 'cái gọi là; được gọi là', 'adjective', '[{"en":"The so-called experts failed to predict the financial crisis.","vi":"Những người được gọi là chuyên gia đã không dự đoán được cuộc khủng hoảng tài chính."},{"en":"Many so-called healthy snacks actually contain a lot of sugar.","vi":"Nhiều loại đồ ăn vặt được gọi là lành mạnh thực ra chứa rất nhiều đường."},{"en":"These gases contribute to the so-called greenhouse effect.","vi":"Những khí này góp phần gây ra cái gọi là hiệu ứng nhà kính."}]', '[{"phrase":"the so-called"},{"phrase":"so-called experts"}]', 'Thường mang ý hoài nghi, mỉa mai', '/ˌsəʊ ˈkɔːld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/so_/so_ca/so_called_1_us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 28, 'straightforward', 'đơn giản, dễ hiểu; thẳng thắn', 'adjective', '[{"en":"The online application process is fairly straightforward and quick.","vi":"Quy trình nộp hồ sơ trực tuyến khá đơn giản và nhanh chóng."},{"en":"There is no straightforward answer to this question.","vi":"Không có câu trả lời đơn giản cho câu hỏi này."},{"en":"She was very straightforward with us about her mistakes.","vi":"Cô ấy rất thẳng thắn với chúng tôi về những sai lầm của mình."}]', '[{"phrase":"fairly straightforward"},{"phrase":"relatively straightforward"},{"phrase":"straightforward answer"},{"phrase":"straightforward process"}]', NULL, '/ˌstreɪtˈfɔːrwərd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strai/straightforward__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 29, 'undergo', 'trải qua', 'verb', '[{"en":"The city has undergone major changes over the past decade.","vi":"Thành phố đã trải qua nhiều thay đổi lớn trong thập kỷ qua."},{"en":"All new drugs must undergo testing before they can be sold.","vi":"Mọi loại thuốc mới đều phải trải qua kiểm nghiệm trước khi được bán."},{"en":"He underwent surgery on his knee last month.","vi":"Anh ấy đã phẫu thuật đầu gối vào tháng trước."}]', '[{"phrase":"undergo surgery"},{"phrase":"undergo changes"},{"phrase":"undergo treatment"},{"phrase":"undergo testing"}]', 'undergo – underwent – undergone', '/ˌʌndərˈɡəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undergo__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('awl-10-01', 30, 'whereby', 'theo đó; nhờ đó', 'adverb', '[{"en":"The company introduced a system whereby staff can work from home.","vi":"Công ty đã áp dụng một hệ thống theo đó nhân viên có thể làm việc tại nhà."},{"en":"Both sides signed an agreement whereby they would share the costs.","vi":"Hai bên đã ký một thỏa thuận, theo đó họ sẽ cùng chia sẻ chi phí."},{"en":"Photosynthesis is the process whereby plants turn sunlight into energy.","vi":"Quang hợp là quá trình nhờ đó thực vật biến ánh sáng mặt trời thành năng lượng."}]', '[{"phrase":"a system whereby"},{"phrase":"an agreement whereby"},{"phrase":"a process whereby"}]', 'Trang trọng; = by which', '/werˈbaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/whereby__us_1_rr.mp3', NULL, NULL);
